<!doctype html><html><head><meta charset=utf8><meta name=viewport content="width=device-width,initial-scale=1,viewport-fit=cover"><style>:root{color-scheme:light;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}html{scroll-padding-top:env(safe-area-inset-top,0px)}body{margin:0;padding:0;font:14px -apple-system,BlinkMacSystemFont,sans-serif;background:#fff;color:#000}img{max-width:100%}[hidden]:not([hidden=until-found i]){display:none!important}</style></head><body>
<title>Maldives Boat Routes</title>
<meta name="claude:viewport-fit-sides" content="cover">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700&family=Source+Sans+3:wght@400;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap">
<style>
/* Layout: chart-table — a side panel (search, filters, layers, details) beside a full-height nautical chart; on phones the panel becomes a bottom sheet. */
:root{
  --sea:#f2f5f6; --sea-grid:#dfe7ea; --reef:#7d97b8; --reef-edge:#4f6a8f; --atoll-fill:#c6d3e2; --lagoon:#c9d7e6; --pa-edge:#2f8a3c; --panel:#f7fafa; --ink:#14303a; --muted:#57717a; --line:#cfdfe2;
  --isle:#f1e3bd; --isle-stroke:#7a6436; --chip:#e8f0f1;
  --ferry:#1f4e8c; --rtl:#2346a8; --gps:#b26b00; --atoll:#16805f; --speed:#d0532a; --road:#86704a; --accent:#0f6f80; --focus:#0f6f80;
  --l-inh:#e6cf8f; --l-res:#c98a2a; --l-ind:#7d8790; --l-uni:#a8b893;
  --l-harb:#2d7fa6; --l-anch:#7556b8; --l-dive:#079096; --l-divec:#3a9e6a; --l-wreck:#7a5a42;
  --l-light:#c99a0c; --l-air:#4f5b6e; --l-prot:#2f8a3c; --l-fad:#b0307f; --l-ice:#4b63e0; --l-hosp:#d1242f; --l-hc:#e5737a; --emerg:#d1242f;
  --dot-stroke:#ffffff; --under:#a61e4d; --under-bg:#f6e3ea;
  --f-display:"Barlow Condensed","Arial Narrow",Arial,sans-serif;
  --f-body:"Source Sans 3","Segoe UI",system-ui,sans-serif;
  --f-mono:"IBM Plex Mono",ui-monospace,Menlo,monospace;
}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){
  --sea:#0d1c23; --sea-grid:#18303a; --reef:#2b4663; --reef-edge:#4c6f96; --atoll-fill:#14273a; --lagoon:#16293a; --pa-edge:#68c776; --panel:#111f26; --ink:#e3eef0; --muted:#8fa8b0; --line:#22383f;
  --isle:#d8c48f; --isle-stroke:#f3e4b8; --chip:#1a2e36;
  --ferry:#6fa3ea; --rtl:#8fa8ff; --gps:#f0a640; --atoll:#4cc59a; --speed:#f08561; --road:#c2a675; --accent:#5cc3d4; --focus:#5cc3d4;
  --l-inh:#d8c48f; --l-res:#e3a94a; --l-ind:#9aa5b0; --l-uni:#7f9070;
  --l-harb:#5fb5dc; --l-anch:#a98cec; --l-dive:#38cfd3; --l-divec:#66c793; --l-wreck:#c39d7f;
  --l-light:#f0c43c; --l-air:#a9b5c8; --l-prot:#68c776; --l-fad:#ea7cc4; --l-ice:#8ea0ff; --l-hosp:#ff6b6b; --l-hc:#f3a3a8; --emerg:#ff6b6b;
  --dot-stroke:#0d1c23; --under:#f2708f; --under-bg:#3a1a26; color-scheme:dark}}
:root[data-theme="dark"]{
  --sea:#0d1c23; --sea-grid:#18303a; --reef:#2b4663; --reef-edge:#4c6f96; --atoll-fill:#14273a; --lagoon:#16293a; --pa-edge:#68c776; --panel:#111f26; --ink:#e3eef0; --muted:#8fa8b0; --line:#22383f;
  --isle:#d8c48f; --isle-stroke:#f3e4b8; --chip:#1a2e36;
  --ferry:#6fa3ea; --rtl:#8fa8ff; --gps:#f0a640; --atoll:#4cc59a; --speed:#f08561; --road:#c2a675; --accent:#5cc3d4; --focus:#5cc3d4;
  --l-inh:#d8c48f; --l-res:#e3a94a; --l-ind:#9aa5b0; --l-uni:#7f9070;
  --l-harb:#5fb5dc; --l-anch:#a98cec; --l-dive:#38cfd3; --l-divec:#66c793; --l-wreck:#c39d7f;
  --l-light:#f0c43c; --l-air:#a9b5c8; --l-prot:#68c776; --l-fad:#ea7cc4; --l-ice:#8ea0ff; --l-hosp:#ff6b6b; --l-hc:#f3a3a8; --emerg:#ff6b6b;
  --dot-stroke:#0d1c23; --under:#f2708f; --under-bg:#3a1a26; color-scheme:dark}

html,body{height:100%}
body{background:var(--panel);color:var(--ink);font-family:var(--f-body);font-size:15px;line-height:1.45}
*{box-sizing:border-box}
.app{height:calc(100% - 52px);display:grid;grid-template-columns:minmax(300px,380px) 1fr}
.panel{display:flex;flex-direction:column;min-height:0;min-width:0;border-right:1px solid var(--line);background:var(--panel);
  padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:16px}
.head{padding-block:16px 10px;display:flex;flex-direction:column;gap:10px}
.titlerow{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
h1{font-family:var(--f-display);font-weight:700;font-size:28px;letter-spacing:.01em;line-height:1;margin:0;text-wrap:balance}
.sub{color:var(--muted);font-size:13px;margin:4px 0 0}
.search{position:relative}
.search input{width:100%;font:inherit;font-size:15px;padding:10px 12px 10px 36px;border-radius:8px;border:1px solid var(--line);background:var(--sea);color:var(--ink)}
.search input:focus{outline:2px solid var(--focus);outline-offset:1px}
.search svg{position:absolute;left:11px;top:50%;transform:translateY(-50%);width:16px;height:16px;stroke:var(--muted);fill:none;stroke-width:2}
.results{position:absolute;z-index:2000;left:0;right:0;top:calc(100% + 4px);background:var(--panel);border:1px solid var(--line);border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,.18);list-style:none;margin:0;padding:4px;max-height:340px;overflow:auto}
.results li{padding:7px 10px;border-radius:6px;cursor:pointer;display:flex;justify-content:space-between;gap:10px;align-items:baseline}
.results li > span:first-child{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.results li[aria-selected="true"],.results li:hover{background:var(--chip)}
.results .k{color:var(--muted);font-size:12px;white-space:nowrap}
.results .none{color:var(--muted);cursor:default}
.lbl{font-family:var(--f-display);font-weight:600;font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.sw{width:18px;height:0;border-top:3px solid currentColor;display:inline-block}
.sw.ferry{color:var(--ferry)}.sw.rtl{color:var(--rtl)}.sw.gps{color:var(--gps)}.sw.atoll{color:var(--atoll)}.sw.speed{color:var(--speed)}.sw.road{color:var(--road);border-top-style:dashed}
.dot{width:11px;height:11px;border-radius:50%;background:var(--c);display:inline-block;flex:none;box-shadow:0 0 0 1.5px var(--dot-stroke),0 0 0 2.5px color-mix(in srgb,var(--c) 60%,transparent)}
.row2{display:flex;flex-direction:column;gap:8px}
select{font:inherit;font-size:14px;padding:7px 10px;border-radius:8px;border:1px solid var(--line);background:var(--sea);color:var(--ink);width:100%;min-width:0}
.tabs{display:flex;border:1px solid var(--line);border-radius:8px;overflow:hidden}
.tab{flex:1;font:inherit;font-size:13px;font-weight:600;padding:7px 8px;background:var(--panel);color:var(--muted);border:0;cursor:pointer;white-space:nowrap}
.tab#tab-under[aria-selected="true"]{background:var(--under-bg);color:var(--under)}
.tab+.tab{border-left:1px solid var(--line)}
.tab[aria-selected="true"]{background:var(--chip);color:var(--ink)}
.body{flex:1;min-height:0;overflow:auto;padding-block:4px 18px;border-top:1px solid var(--line)}
.group{margin-top:12px}
.item{display:flex;width:100%;text-align:left;gap:10px;align-items:flex-start;font:inherit;color:inherit;background:none;border:0;padding:7px 6px;border-radius:6px;cursor:pointer}
.item:hover{background:var(--chip)}
.item .sw{margin-top:10px;flex:none}
.item .dot{margin-top:5px}
.item .t{font-weight:600}
.item .m{display:block;color:var(--muted);font-size:13px}
.item > span:last-child{min-width:0}
.no{font-family:var(--f-mono);font-size:12px;color:var(--muted);margin-left:4px}
.lgroup{margin-top:14px}
.lgroup .src{font-size:12px;color:var(--muted);margin-left:6px;text-transform:none;letter-spacing:0;font-family:var(--f-body);font-weight:400}
.lyr{display:flex;align-items:center;gap:10px;padding:5px 4px;border-radius:6px;cursor:pointer}
.lyr:hover{background:var(--chip)}
.lyr input{accent-color:var(--accent);width:16px;height:16px;margin:0}
.lyr .n{margin-left:auto;font-family:var(--f-mono);font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums}
.lyr-actions{display:flex;gap:12px;margin-top:6px}
.linkbtn{font:inherit;font-size:13px;color:var(--accent);background:none;border:0;padding:4px 0;cursor:pointer}
.detail h2{font-family:var(--f-display);font-size:26px;line-height:1.05;margin:10px 0 4px;text-wrap:balance}
.dv{font-size:16px;color:var(--muted);margin:0 0 6px}
.back{font:inherit;font-size:13px;color:var(--accent);background:none;border:0;padding:6px 0;cursor:pointer}
.badge{display:inline-flex;align-items:center;gap:6px;font-size:12px;padding:2px 8px;border-radius:999px;background:var(--chip);color:var(--ink)}
.facts{display:grid;grid-template-columns:auto 1fr;gap:4px 14px;margin:12px 0;font-size:14px}
.facts dt{color:var(--muted)}
.facts dd{margin:0;min-width:0}
.facts button{font:inherit;color:var(--accent);background:none;border:0;padding:0;cursor:pointer;text-align:left}
.mono{font-family:var(--f-mono);font-size:13px;font-variant-numeric:tabular-nums}
.units{width:100%;border-collapse:collapse;font-size:13px;margin:6px 0 4px}
.units th{text-align:left;color:var(--muted);font-weight:600;padding:4px 6px 4px 0;border-bottom:1px solid var(--line)}
.units td{padding:5px 6px 5px 0;border-bottom:1px solid var(--line);vertical-align:top}
.heatbox{background:var(--chip);border-radius:10px;padding:12px;margin-top:12px}
.legend{display:grid;grid-template-columns:auto 1fr auto;gap:8px;align-items:center;font-size:12px;color:var(--muted);margin:8px 0}
.grad{height:10px;border-radius:5px}
.wrow{display:grid;grid-template-columns:1fr auto;gap:2px 10px;margin:10px 0 0;font-size:14px}
.wrow input{grid-column:1/-1;width:100%;accent-color:var(--accent)}
.wrow .m{grid-column:1/-1;font-size:12px;color:var(--muted)}
.wv{font-family:var(--f-mono);font-size:13px}
.yrow{display:grid;grid-template-columns:auto 1fr;gap:10px;align-items:center;font-size:14px;margin-top:8px}
.score{display:flex;align-items:baseline;gap:10px;margin:6px 0}
.score b{font-family:var(--f-display);font-size:34px;line-height:1}
.bars{display:flex;flex-direction:column;gap:8px;margin:8px 0}
.bar{display:grid;grid-template-columns:1fr auto;gap:2px 8px;font-size:13px}
.bar .track{grid-column:1/-1;height:8px;border-radius:4px;background:var(--line);overflow:hidden}
.bar .fill{height:100%;border-radius:4px}
.bar .m{grid-column:1/-1;color:var(--muted);font-size:12px}
.hdot{width:12px;height:12px;border-radius:50%;display:inline-block;flex:none;margin-top:4px;box-shadow:0 0 0 1.5px var(--dot-stroke)}
.tt{width:100%;border-collapse:collapse;font-size:13px;margin:6px 0}
.tt th{text-align:left;color:var(--muted);font-weight:600;padding:3px 6px 3px 0;border-bottom:1px solid var(--line)}
.tt td{padding:4px 6px 4px 0;border-bottom:1px solid var(--line);font-variant-numeric:tabular-nums}
.tt td.seen{color:var(--gps);font-weight:600}
.deps{display:flex;flex-wrap:wrap;gap:4px;margin:6px 0}
.deps span{font-family:var(--f-mono);font-size:12px;background:var(--chip);border-radius:4px;padding:1px 6px}
.units td.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
.tw{overflow-x:auto}
.stops{list-style:none;margin:8px 0 0;padding:0}
.stops li{position:relative;padding:0 0 12px 22px}
.stops li::before{content:"";position:absolute;left:4px;top:6px;width:9px;height:9px;border-radius:50%;background:var(--isle);border:2px solid var(--isle-stroke)}
.stops li:not(:last-child)::after{content:"";position:absolute;left:9px;top:17px;bottom:-2px;border-left:2px solid var(--line)}
.stops button{font:inherit;font-weight:600;background:none;border:0;padding:0;color:var(--ink);cursor:pointer;text-align:left}
.stops button:hover{color:var(--accent);text-decoration:underline}
.leg{display:block;color:var(--muted);font-size:12px}
.note{font-size:13px;color:var(--muted);margin:10px 0}
.warn{font-size:13px;margin:10px 0;padding:8px 10px;border-radius:6px;background:var(--chip);border-left:3px solid var(--l-light)}
.ext{color:var(--accent)}
.foot{font-size:12px;color:var(--muted);border-top:1px solid var(--line);margin-top:16px;padding-top:10px}
.foot p{margin:0 0 6px}
.toggle{display:none}

#map{position:relative;height:100%;background:var(--sea);min-width:0}
/* Leaflet core (inlined) */
.leaflet-pane,.leaflet-tile,.leaflet-marker-icon,.leaflet-tile-container,.leaflet-pane>svg,.leaflet-pane>canvas,.leaflet-zoom-box,.leaflet-layer{position:absolute;left:0;top:0}
.leaflet-container{overflow:hidden;-webkit-tap-highlight-color:transparent;font-family:var(--f-body)}
.leaflet-container.leaflet-touch-drag{touch-action:none}
.leaflet-container .leaflet-overlay-pane svg{max-width:none!important;max-height:none!important}
.leaflet-pane{z-index:400}.leaflet-overlay-pane{z-index:400}.leaflet-marker-pane{z-index:600}.leaflet-tooltip-pane{z-index:650}
.leaflet-map-pane canvas{z-index:100}.leaflet-map-pane svg{z-index:200}
.leaflet-pane>svg path{pointer-events:none}
.leaflet-pane>svg path.leaflet-interactive{pointer-events:visiblePainted;pointer-events:auto}
.leaflet-zoom-animated{transform-origin:0 0}
.leaflet-zoom-anim .leaflet-zoom-animated{transition:transform .25s cubic-bezier(0,0,.25,1)}
.leaflet-zoom-anim .leaflet-zoom-hide{visibility:hidden}
.leaflet-interactive{cursor:pointer}
.leaflet-grab{cursor:grab}.leaflet-dragging .leaflet-grab,.leaflet-dragging .leaflet-interactive{cursor:grabbing}
.leaflet-control{position:relative;z-index:800;pointer-events:auto;float:left;clear:both}
.leaflet-top,.leaflet-bottom{position:absolute;z-index:1000;pointer-events:none}
.leaflet-top{top:0}.leaflet-right{right:0}.leaflet-bottom{bottom:0}.leaflet-left{left:0}
.leaflet-right .leaflet-control{float:right}
.leaflet-top .leaflet-control{margin-top:12px}.leaflet-bottom .leaflet-control{margin-bottom:12px}
.leaflet-right .leaflet-control{margin-right:max(12px,env(safe-area-inset-right,0px))}.leaflet-left .leaflet-control{margin-left:12px}
.leaflet-bar{border-radius:8px;overflow:hidden;border:1px solid var(--line);background:var(--panel)}
.leaflet-bar a,.leaflet-bar button{display:block;width:34px;height:34px;line-height:32px;text-align:center;text-decoration:none;color:var(--ink);font-size:20px;background:var(--panel);border:0;padding:0;cursor:pointer;font-family:var(--f-body)}
.leaflet-bar a+a{border-top:1px solid var(--line)}
.leaflet-bar a:hover,.leaflet-bar button:hover{background:var(--chip)}
.leaflet-bar button svg{width:18px;height:18px;stroke:currentColor;fill:none;stroke-width:2;vertical-align:middle}
.leaflet-control-scale-line{border:2px solid var(--muted);border-top:none;line-height:1.1;padding:2px 5px 1px;font-size:11px;white-space:nowrap;color:var(--ink);background:color-mix(in srgb,var(--panel) 70%,transparent)}
.leaflet-tooltip{position:absolute;white-space:nowrap;pointer-events:none;user-select:none}
.leaflet-tooltip-right{margin-left:7px}.leaflet-tooltip-left{margin-left:-7px}.leaflet-tooltip-top{margin-top:-8px}
.leaflet-fade-anim .leaflet-tooltip{transition:opacity .2s}

/* Chart styling */
.grat{stroke:var(--sea-grid);stroke-width:1}
.eq{stroke:var(--muted);stroke-width:1;stroke-dasharray:6 6;opacity:.6}
.rt{fill:none;stroke-width:3;stroke-linecap:round;stroke-linejoin:round;transition:stroke-opacity .2s,stroke-width .2s}
.rt-ferry{stroke:var(--ferry)}.rt-rtl{stroke:var(--rtl)}.rt-atoll{stroke:var(--atoll)}.rt-speed{stroke:var(--speed)}.rt-road{stroke:var(--road);stroke-dasharray:4 5}
.rt.dim{stroke-opacity:.14}
.rt.unv{stroke-dasharray:2 6;stroke-width:2}
.rt.sel{stroke-width:5.5}
.rt.flow{stroke-dasharray:10 9;animation:flow 1.1s linear infinite}
@keyframes flow{to{stroke-dashoffset:-19}}
.hit{stroke:transparent;stroke-width:16;fill:none}
.isle{fill:var(--isle);stroke:var(--isle-stroke);stroke-width:1.6}
.isle.dim{opacity:.3}
.isle.sel{stroke:var(--accent);stroke-width:3}
.pin{fill:none;stroke:var(--accent);stroke-width:3}
.isle-label{font-family:var(--f-display);font-weight:600;font-size:13px;letter-spacing:.02em;color:var(--ink);text-shadow:0 0 3px var(--sea),0 0 3px var(--sea),0 0 6px var(--sea);display:none}
.isle-label.minor{font-weight:500;font-size:12px;color:var(--muted)}
.show-labels .isle-label:not(.minor),.show-minor .isle-label.minor,.isle-label.hub,.isle-label.on{display:block}
.isle-label.on{color:var(--accent)}
.atoll-label{font-family:var(--f-display);font-weight:500;font-size:12px;letter-spacing:.32em;color:var(--muted);opacity:.85;white-space:nowrap;transform:translateX(-50%)}
.hover-tip{background:var(--panel);color:var(--ink);border:1px solid var(--line);border-radius:6px;padding:4px 8px;font-size:13px;box-shadow:0 4px 12px rgba(0,0,0,.15)}
.eq-label{font-family:var(--f-mono);font-size:11px;color:var(--muted);white-space:nowrap}

/* Underserved islands overlays */
.periph{stroke:var(--under);stroke-width:1.5;stroke-dasharray:3 4;fill:var(--under);fill-opacity:.07}
.trunk{stroke:var(--under);stroke-width:3;stroke-dasharray:12 6;fill:none;stroke-linecap:round;opacity:.85}
.feeder{stroke:var(--under);stroke-width:1.4;stroke-dasharray:2 4;fill:none;stroke-linecap:round;opacity:.75}
.emerg{stroke:var(--emerg);stroke-width:1.6;fill:none;opacity:.85}
.emerg2{stroke:var(--emerg);stroke-width:3;fill:none;opacity:.8}
.feeder.assumed,.emerg.assumed,.emerg2.assumed{stroke-dasharray:5 5;opacity:.5}
.verify{list-style:none;margin:8px 0;padding:0;display:flex;flex-direction:column;gap:12px}
.verify li{display:grid;grid-template-columns:auto 1fr;gap:10px;align-items:start;font-size:14px}
.verify .t{font-weight:600;display:block}
.verify .m{display:block;color:var(--muted);font-size:13px;margin:2px 0}
.verify .cite{display:block}
.vs{font-size:11px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;padding:2px 7px;border-radius:999px;color:var(--c);border:1.5px solid var(--c);white-space:nowrap;margin-top:2px}
.hubs{display:flex;flex-direction:column;gap:10px;margin-top:8px}
.hub .t{font-weight:600}
.hub .m{font-size:13px;color:var(--muted)}
.cite a{color:var(--accent)}
.tsw.emerg{border-top:2px solid var(--emerg);opacity:1}
.tsw.emerg2{border-top:3px solid var(--emerg)}
.focus{stroke:var(--under);stroke-width:3;fill:var(--under);fill-opacity:.15}
.under-label{font-family:var(--f-display);font-weight:700;font-size:13px;color:var(--under);text-shadow:0 0 3px var(--sea),0 0 3px var(--sea),0 0 6px var(--sea)}
.callout{margin:12px 0;padding:10px 12px;border-radius:8px;background:var(--under-bg);border-left:3px solid var(--under);font-size:14px}
.callout .lbl{color:var(--under)}
.callout p{margin:4px 0}
.cite{color:var(--muted);font-size:12px}
.tiers{list-style:none;margin:8px 0;padding:0;display:flex;flex-direction:column;gap:10px}
.tiers li{display:grid;grid-template-columns:28px 1fr;gap:10px;align-items:start;font-size:14px}
.tiers .t{font-weight:600}
.tiers .m{display:block;color:var(--muted);font-size:13px}
.tsw{width:28px;height:0;margin-top:10px;border-top:3px dashed var(--under)}
.tsw.feed{border-top:2px dotted var(--under)}
.stat{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:10px 0}
.stat div{background:var(--chip);border-radius:8px;padding:8px 10px}
.stat b{display:block;font-family:var(--f-display);font-size:22px;line-height:1.1;font-variant-numeric:tabular-nums}
.stat span{font-size:12px;color:var(--muted)}
.intro{font-size:14px;margin:10px 0}

@media (prefers-reduced-motion: reduce){.rt.flow{animation:none;stroke-dasharray:none}}

@media (max-width:760px){
  .app{grid-template-columns:1fr;grid-template-rows:1fr auto}
  #map{grid-row:1}
  .panel{grid-row:2;border-right:0;border-top:1px solid var(--line);max-height:56vh;padding-right:max(16px,env(safe-area-inset-right,0px));padding-bottom:env(safe-area-inset-bottom,0px)}
  .panel.collapsed .body,.panel.collapsed .filters{display:none}
  .head{padding-block:10px 8px;gap:8px}
  h1{font-size:22px}
  .sub{display:none}
  .toggle{display:inline-flex;font:inherit;font-size:13px;background:var(--chip);border:1px solid var(--line);color:var(--ink);border-radius:999px;padding:4px 12px;cursor:pointer;white-space:nowrap}
}

@media (min-width:761px){
  .app{grid-template-columns:1fr;grid-template-rows:auto 1fr}
  #map{min-height:0}
  .panel{border-right:0;border-bottom:1px solid var(--line);padding-right:max(16px,env(safe-area-inset-right,0px))}
  .titlerow{display:none}

  /* controls in one horizontal row */
  .head{flex-direction:row;flex-wrap:wrap;align-items:center;gap:10px 14px;padding-block:10px}
  .search{flex:1 1 280px;max-width:360px}
  .filters{flex:1 1 auto;flex-direction:row!important;flex-wrap:wrap;align-items:center;gap:10px 14px!important}
  .filters .row2{flex-direction:row;flex-wrap:wrap;align-items:center;gap:10px}
  .filters select{width:auto;min-width:200px}
  .filters .route-type{min-width:150px}
.search-and-filters { display: flex; align-items: center; gap: 10px; }
.search-and-filters .search { flex-grow: 1; }
.search-and-filters .row2 { flex-direction: row; gap: 10px; }

  /* route list flows sideways in columns instead of one long vertical list */
  .body{flex:none;height:24vh;min-height:150px;column-width:290px;column-gap:24px;column-fill:auto;overflow:auto;padding-block:10px}
  .body .item{break-inside:avoid}
  .body .lbl{break-after:avoid}
}

/* route-type dropdown */
.dd{position:relative;min-width:0}
.dd summary{list-style:none;cursor:pointer;font:inherit;font-size:14px;padding:7px 30px 7px 10px;border-radius:8px;border:1px solid var(--line);background:var(--sea);color:var(--ink);white-space:nowrap;position:relative;user-select:none}
.dd summary::-webkit-details-marker{display:none}
.dd summary::after{content:"";position:absolute;right:11px;top:50%;width:6px;height:6px;border-right:2px solid var(--muted);border-bottom:2px solid var(--muted);transform:translateY(-70%) rotate(45deg)}
.dd summary:focus-visible,.dd[open] summary{outline:2px solid var(--focus);outline-offset:1px}
.dd-menu{position:absolute;z-index:2000;top:calc(100% + 4px);left:0;min-width:240px;max-width:90vw;background:var(--panel);border:1px solid var(--line);border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,.18);padding:4px}
.dd-opt{display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:6px;cursor:pointer}
.dd-opt:hover{background:var(--chip)}
.dd-opt input{accent-color:var(--accent);width:16px;height:16px;margin:0}
.dd-sep{border-top:1px solid var(--line);margin:4px 0}
@media (max-width:760px){.dd summary{width:100%}.dd-menu{left:0;right:0}}

</style>


@include('Both.navbar')

