{const seen={};D.poi["hospitals"]=D.moh.hospitals.map(([name,id,type,lic,status,sector,placed,reg,owner])=>{const i=I[id];const k=seen[id]=(seen[id]||0)+1;
  return [name,ATOLLS.indexOf(i.atoll),i.lat,i.lon+(k-1)*0.0025,null,id,0,{type,lic,status,placed,reg,owner,nudged:k>1}];});}
