  {id:"sb-dhg", unv:true, name:"Speedboat: Malé – Dhangethi – Dhigurah", type:"speed", stops:["male","adh-dhangethi","adh-dhigurah"], days:"Not known"}
];
// Official RTL Zone 1 routes, parsed from MTCC's timetable PDF
const shortName = id => (I[id]?I[id].name:id);
(D.rtl||[]).forEach(r=>ROUTES.push({id:"rtl-"+r.code, no:r.code, name:r.name||r.stops.map(shortName).join(" – "), type:"rtl", stops:r.stops,
  legs:r.legs, days:r.zone===1?"Every day ("+r.days+")":r.days, effective:r.effective, title:r.title, zone:r.zone, src:r.src,
  note:r.note||(r.code==="S2C3"?"MTCC's route map labels this line S2C4 and adds Maroshi; the timetable calls it S2C3 and starts at Komandoo.":null)}));
const R = Object.fromEntries(ROUTES.map(r=>[r.id,r]));
// GPS-observed links (1 Aug 2025)
const LINKS = (D.links||[]).map((l,idx)=>({...l,idx}));
const LINKBY = Object.fromEntries(LINKS.map(l=>[[l.a,l.b].sort().join("|"),l]));
const linkFor=(a,b)=>LINKBY[[a,b].sort().join("|")];
ISL.forEach(i=>i.routes=[]);
ROUTES.forEach(r=>r.stops.forEach(s=>I[s].routes.push(r.id)));
const ROUTE_ISLES = ISL.filter(i=>i.routes.length);

// ---------- geometry ----------
function km(a,b){const R=6371,t=Math.PI/180,dl=(b.lat-a.lat)*t,dn=(b.lon-a.lon)*t;
  const h=Math.sin(dl/2)**2+Math.cos(a.lat*t)*Math.cos(b.lat*t)*Math.sin(dn/2)**2;return 2*R*Math.asin(Math.sqrt(h));}
const nmi = k => k/1.852;
function curve(a,b,bend){
  if(!bend) return [[a.lat,a.lon],[b.lat,b.lon]];
  const mx=(a.lat+b.lat)/2, my=(a.lon+b.lon)/2, dx=b.lat-a.lat, dy=b.lon-a.lon;
  const cx=mx-dy*bend, cy=my+dx*bend, pts=[];
  for(let i=0;i<=24;i++){const t=i/24,u=1-t;pts.push([u*u*a.lat+2*u*t*cx+t*t*b.lat,u*u*a.lon+2*u*t*cy+t*t*b.lon]);}
  return pts;
}
const BEND={rtl:.06,ferry:.07,atoll:.1,speed:.2,road:0};
function dms(v,pos,neg){const h=v<0?neg:pos;v=Math.abs(v);const d=Math.floor(v),m=(v-d)*60;return `${d}°${m.toFixed(3).padStart(6,"0")}′${h}`;}

// ---------- map ----------
const map = L.map("map",{zoomControl:false,attributionControl:false,minZoom:5.5,maxZoom:15,zoomSnap:.5});
const canvas = L.canvas({padding:.5,tolerance:6});
L.control.zoom({position:"topright"}).addTo(map);
const AllCtl = L.Control.extend({options:{position:"topright"},onAdd(){
  const d=L.DomUtil.create("div","leaflet-bar");
  d.innerHTML=`<button type="button" title="Show all of the Maldives" aria-label="Show all of the Maldives"><svg viewBox="0 0 24 24"><path d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5"/></svg></button>`;
  L.DomEvent.disableClickPropagation(d);
  d.firstChild.addEventListener("click",()=>map.flyToBounds(L.latLngBounds(ISL.map(i=>[i.lat,i.lon])),{padding:[20,20],duration:.6}));
  return d;}});
new AllCtl().addTo(map);
L.control.scale({imperial:false,position:"bottomright"}).addTo(map);

// ---------- base map: MLSA surveyed reefs, lagoons, protected areas ----------
map.createPane("survey"); map.getPane("survey").style.zIndex=350; map.getPane("survey").style.pointerEvents="none";
const surveyR = L.canvas({pane:"survey",padding:.5});
function decRing(r){const out=[];let x=0,y=0;for(let k=0;k<r.length;k+=2){x+=r[k];y+=r[k+1];out.push([y/1e4,x/1e4]);}return out;}
const BASE = [
  {key:"atoll", label:"Atoll areas (traced from reefs)", on:true, style:()=>({fill:true,fillColor:css("--atoll-fill"),fillOpacity:1,stroke:false})},
  {key:"reef", label:"Reefs (atoll shapes)", on:true, style:()=>({fill:true,fillColor:css("--reef"),fillOpacity:.9,color:css("--reef-edge"),weight:.8})},
  {key:"lagoon", label:"Island lagoons", on:true, style:()=>({fill:true,fillColor:css("--lagoon"),fillOpacity:1,color:css("--reef-edge"),weight:.4})},
  {key:"protected_area", label:"Protected area outlines", on:false, style:()=>({fill:true,fillColor:css("--pa-edge"),fillOpacity:.08,color:css("--pa-edge"),weight:1.2,dashArray:"4 3"})}
];
const BS = Object.fromEntries(BASE.map(b=>[b.key,b]));
BASE.forEach(b=>{b.group=L.layerGroup();b.count=b.key==="atoll"?D.atollShapes.length:(D.outlines[b.key]||[]).length;});
function buildBase(b){
  const st=b.style();
  if(b.key==="atoll"){b.polys=D.atollShapes.map(s=>L.polygon(s,{renderer:surveyR,pane:"survey",interactive:false,...st}).addTo(b.group));return;}
  b.polys=(D.outlines[b.key]||[]).map(([name,code,rings])=>L.polygon(rings.map(decRing),{renderer:surveyR,pane:"survey",interactive:false,...st}).addTo(b.group));
}
function syncBase(){
  let changed=false;
  BASE.forEach(b=>{if(b.on&&!b.polys)buildBase(b);const has=map.hasLayer(b.group);if(b.on!==has)changed=true;});
  if(!changed) return;
  BASE.forEach(b=>{if(map.hasLayer(b.group))b.group.remove();});   // re-add in order so lower layers paint first
  BASE.forEach(b=>{if(b.on)b.group.addTo(map);});
}
function recolorBase(){BASE.forEach(b=>{if(!b.polys)return;const st=b.style();b.polys.forEach(p=>p.setStyle(st));});}

for(let lat=-1.5;lat<=8;lat+=.5) L.polyline([[lat,71.5],[lat,74.5]],{className:"grat",interactive:false}).addTo(map);
for(let lon=71.5;lon<=74.5;lon+=.5) L.polyline([[-1.5,lon],[8,lon]],{className:"grat",interactive:false}).addTo(map);
L.polyline([[0,71.5],[0,74.5]],{className:"eq",interactive:false}).addTo(map);
L.marker([0,72.2],{interactive:false,icon:L.divIcon({className:"eq-label",html:"EQUATOR 0°",iconSize:null})}).addTo(map);
const ATOLL_LABEL = {"Seenu":"SEENU · ADDU","Gnaviyani":"GNAVIYANI","Malé City":null};
ATOLLS.forEach((a,k)=>{
  if(ATOLL_LABEL[a]===null) return;
  let [la,lo]=D.atollCentres[k]; if(a==="Gnaviyani") la+=.09; if(a==="Kaafu") la+=.25;
  L.marker([la,lo],{interactive:false,keyboard:false,icon:L.divIcon({className:"atoll-label",html:ATOLL_LABEL[a]||a.toUpperCase(),iconSize:null})}).addTo(map);
});

function css(v){return getComputedStyle(document.documentElement).getPropertyValue(v).trim();}

// routes
const rLayers={};
ROUTES.forEach((r,idx)=>{
  const sign = r.type==="speed" ? (idx%2?1:-1) : 1;
  let pts=[];
  r.gpsLegs=0;
  for(let k=0;k<r.stops.length-1;k++){
    const a=r.stops[k], b=r.stops[k+1], lk=r.type==="rtl"?linkFor(a,b):null;
    let seg;
    if(lk){ seg=(lk.a===a?lk.path:lk.path.slice().reverse()).slice(); seg[0]=[I[a].lat,I[a].lon]; seg[seg.length-1]=[I[b].lat,I[b].lon]; r.gpsLegs++; }
    else seg=curve(I[a],I[b],BEND[r.type]*sign);
    pts=pts.concat(k?seg.slice(1):seg);
  }
  const line=L.polyline(pts,{className:"rt rt-"+r.type+(r.unv?" unv":""),interactive:false});
  const hit=L.polyline(pts,{className:"hit"});
  hit.bindTooltip(r.name,{sticky:true,className:"hover-tip",direction:"top"});
  hit.on("click",e=>{L.DomEvent.stopPropagation(e);select({kind:"route",id:r.id},true);});
  r.km=r.stops.slice(1).reduce((s,id,k)=>s+km(I[r.stops[k]],I[id]),0);
  rLayers[r.id]={line,hit,pts};
});
// route islands (SVG, on top)
const iLayers={};
ROUTE_ISLES.forEach(i=>{
  const m=L.circleMarker([i.lat,i.lon],{radius:i.id==="male"?8:i.cap?6.5:5,className:"isle",bubblingMouseEvents:false});
  m.bindTooltip(i.name,{permanent:true,direction:"right",className:"isle-label"+(i.cap?" hub":""),interactive:false});
  m.on("click",()=>select({kind:"isle",id:i.id},true));
  iLayers[i.id]=m;
});
// point layers (canvas)
function makeMarker(l,it){
  const m=L.circleMarker([it.lat,it.lon],{renderer:canvas,radius:l.r,weight:1.2,color:css("--dot-stroke"),fillColor:css(l.c),fillOpacity:.95,bubblingMouseEvents:false});
  if(it.kind==="isle"&&it.cat==="i"&&!it.routes.length) m.bindTooltip(it.name,{permanent:true,direction:"right",className:"isle-label minor",interactive:false});
  else m.bindTooltip(it.name,{className:"hover-tip",direction:"top",offset:[0,-4]});
  m.on("click",()=>select(it.kind==="isle"?{kind:"isle",id:it.id}:{kind:"poi",layer:l.key,idx:it.idx},false));
  return m;
}
function recolor(){
  recolorBase();
  if(typeof paintHeat==="function") paintHeat();
  recolorGps();
  LAYERS.forEach(l=>{if(!l.markers)return;const f=css(l.c),s=css("--dot-stroke");l.markers.forEach(m=>m.setStyle({fillColor:f,color:s}));});
}
matchMedia("(prefers-color-scheme: dark)").addEventListener("change",recolor);
new MutationObserver(recolor).observe(document.documentElement,{attributes:true,attributeFilter:["data-theme"]});

const pin=L.circleMarker([0,0],{radius:11,className:"pin",interactive:false});

// ---------- GPS-observed sailings ----------
map.createPane("gps"); map.getPane("gps").style.zIndex=390;
const gpsR = L.canvas({pane:"gps",padding:.5,tolerance:5});
const GPSL = [
  {key:"public", label:"Between inhabited islands and the airport", on:true},
  {key:"resort", label:"To and from resorts", on:false},
  {key:"other", label:"Other (industrial, uninhabited)", on:false}
];
const GL = Object.fromEntries(GPSL.map(g=>[g.key,g]));
GPSL.forEach(g=>{g.group=L.layerGroup();g.count=LINKS.filter(l=>l.kind===g.key).length;});
function gpsStyle(l,hot){return {renderer:gpsR,pane:"gps",color:hot?css("--accent"):css("--gps"),weight:(hot?2.5:1)+Math.log2(1+l.trips)*1.1,opacity:hot?1:(l.kind==="public"?.85:.55),dashArray:l.kind==="resort"?"4 4":null,lineCap:"round"};}
LINKS.forEach(l=>{
  l.line=L.polyline(l.path,gpsStyle(l,false));
  l.line.bindTooltip(`${shortName(l.a)} ↔ ${shortName(l.b)} · ${l.trips} trip${l.trips>1?"s":""}`,{sticky:true,className:"hover-tip",direction:"top"});
  l.line.on("click",e=>{L.DomEvent.stopPropagation(e);select({kind:"link",idx:l.idx},false);});
  l.line.addTo(GL[l.kind].group);
});
let hotLink=null;
function syncGps(){
  GPSL.forEach(g=>{if(g.on&&!map.hasLayer(g.group))g.group.addTo(map);else if(!g.on&&map.hasLayer(g.group))g.group.remove();});
  const want=state.sel&&state.sel.kind==="link"?LINKS[state.sel.idx]:null;
  if(hotLink&&hotLink!==want){hotLink.line.setStyle(gpsStyle(hotLink,false));hotLink=null;}
  if(want){ if(!GL[want.kind].on){GL[want.kind].on=true;want.line.addTo(map);GL[want.kind].group.addTo(map);} want.line.setStyle(gpsStyle(want,true));want.line.bringToFront();hotLink=want;}
}
function recolorGps(){LINKS.forEach(l=>l.line.setStyle(gpsStyle(l,l===hotLink)));}

// ---------- underserved islands (user's research summary, checked against its sources) ----------
const SRC = {
  doc:{t:"Your document: Consensus research summary, “What are the underserved islands in maldives…”, 23 Oct 2026"},
  maaharaa:{t:"Ministry of Health, Health Care Facilities register (Maaharaa)", u:"https://maaharaa.health.gov.mv/Public/Home/ListHealthCare"},
  mohTiers:{t:"Ministry of Health, “The health care”", u:"https://health.gov.mv/en/ministry-of-health"},
  aeh:{t:"PSM News, “Major projects underway to expand services at Addu Equatorial Hospital”", u:"https://psmnews.mv/en/182160"},
  thinHosp:{t:"President's Office, 26 Aug 2013, Thinadhoo Regional Hospital to be renamed", u:"https://presidency.gov.mv/Press/Article/13189"},
  kulhPort:{t:"Edition.mv, 20 May 2025, “MPL awarded contract for Kulhudhuffushi Commercial Port expansion”", u:"https://edition.mv/business/41353"},
  ports:{t:"Marine Insight, “Major cargo ports in Maldives”", u:"https://www.marineinsight.com/major-cargo-ports-in-maldives/"},
  adduPort:{t:"PSM News, “Addu International Port development to begin in November”", u:"https://www.psmnews.mv/en/109961"},
  thinPort:{t:"PSM News, “MTCC begins Phase 2 of Thinadhoo Regional Port development”", u:"https://www.psmnews.mv/en/99756"},
  thinShip:{t:"Maritime Gateway, “Cargo shipping service between India and Thinadhoo”", u:"https://www.maritimegateway.com/cargo-shipping-service-between-india-and-thinadhoo/"},
  duvat19:{t:"Duvat & Magnan (2019), Scientific Reports 9:15129, Figure 2", u:"https://pmc.ncbi.nlm.nih.gov/articles/PMC6805953"},
  eya23:{t:"Eya et al. (2023), Public Health Challenges 2(3):e114", u:"https://pmc.ncbi.nlm.nih.gov/articles/PMC12039589"},
  hinkel23:{t:"Hinkel et al. (2023), Climate Services 31:100401 (abstract)", u:"https://saruna.mnu.edu.mv/handle/123456789/16648"},
  aboo14:{t:"Aboobakuru (2014), UNESCAP Transport and Communications Bulletin 84 (abstract)", u:"https://saruna.mnu.edu.mv/items/f091d6df-6f4b-4e42-8e0d-0705136fb6d0/full"},
  acciarri21:{t:"Acciarri et al. (2021), Sustainability 13(6):3484", u:"https://www.mdpi.com/2071-1050/13/6/3484"},
  farhath25:{t:"Farhath et al. (2025), Earth 6(3):66", u:"https://www.mdpi.com/2673-4834/6/3/66"},
  undp19:{t:"UNDP, 16 June 2019", u:"https://www.undp.org/node/181726"},
  register:{t:"MLSA island register (Dhuveli Atlas)", u:"https://atlas.dhuveli.com/islands/adh-mandhoo"}
};
const cite=(...ks)=>ks.map(k=>SRC[k].u?`<a class="ext" href="${SRC[k].u}" target="_blank" rel="noopener">${esc(SRC[k].t)}</a>`:esc(SRC[k].t)).join("; ");

const UNDER = {
  atolls:["Haa Alifu","Haa Dhaalu","Shaviyani","Gaafu Alifu","Gaafu Dhaalu","Seenu"],
  north:["Haa Alifu","Haa Dhaalu","Shaviyani"],
  focus:["ha-filladhoo","ha-uligamu","adh-mandhoo"]
};
const PORT = LY["harbours"].items.find(h=>h.name==="MPL Dock") || I["male"];
const harbourAt = n => LY["harbours"].items.find(h=>h.name===n);
// Freight hubs, verified from public sources
const FHUBS = {
  kulh:{name:"Kulhudhuffushi Commercial Port", island:"hdh-kulhudhuffushi", at:harbourAt("HD. Kulhuduffushi Port"), status:"Operating since 2005; MPL contracted to expand it in 2025",
        role:"Logistics hub for the northern region, serving Haa Alifu, Haa Dhaalu, Shaviyani and Noonu.", src:["kulhPort","ports"], verified:true},
  thin:{name:"Thinadhoo Regional Port", island:"gdh-thinadhoo", at:null, status:"Under development by MTCC (phase 2)",
        role:"Regional port for Gaafu Dhaalu. Cargo ships from India already call at Thinadhoo, and officials want the Huvadhu (Gaafu) region to regain its role as a commercial hub.", src:["thinPort","thinShip"], verified:true},
  hith:{name:"Hithadhoo Regional Port (Addu)", island:"s-hithadhoo", at:harbourAt("Hithadhoo Port - MPL"), status:"Operating since 2009; being redeveloped as Addu International Port",
        role:"Main distribution centre for the southern region, operated by Maldives Ports Limited.", src:["ports","adduPort"], verified:true}
};
Object.values(FHUBS).forEach(h=>{const i=I[h.island];h.lat=h.at?h.at.lat:i.lat;h.lon=h.at?h.at.lon:i.lon;});
// Which freight hub serves each underserved atoll, and whether a source says so
const ATOLL_FHUB = {
  "Haa Alifu":{hub:"kulh",ok:true}, "Haa Dhaalu":{hub:"kulh",ok:true}, "Shaviyani":{hub:"kulh",ok:true},
  "Gaafu Dhaalu":{hub:"thin",ok:true},
  "Gaafu Alifu":{hub:"thin",ok:false,why:"No regional port of its own was found. Thinadhoo is the nearest regional port and serves the wider Huvadhu (Gaafu) region, so the map assumes it."},
  "Seenu":{hub:"hith",ok:true}
};
// Health centres whose parent hospital the register states
const HC_PARENT = {
  "Addu Equatorial Hospital":["s-feydhoo","s-maradhoo"],
  "Dr. Abdul Samad Memorial Hospital":["gdh-madaveli","gdh-hoadehdhoo","gdh-nadellaa","gdh-gahdhoo","gdh-rathafandhoo","gdh-vaadhoo","gdh-fiyoari","gdh-faresmaathodaa"],
  "Shaviyani Atoll Hospital":["sh-komandoo","sh-maaungoodhoo","sh-bileiyfahi","sh-milandhoo","sh-kanditheemu","sh-foakaidhoo","sh-maroshi","sh-narudhoo","sh-lhaimagu","sh-feevah"]
};
// Atoll hospital for each atoll (same-atoll assumption where the register is silent)
const ATOLL_HOSP = {"Haa Alifu":"Haa Alifu Atoll Hospital","Haa Dhaalu":"Kulhudhuffushi Regional Hospital","Shaviyani":"Shaviyani Atoll Hospital",
  "Gaafu Alifu":"Gaafu Alifu Atoll Hospital","Gaafu Dhaalu":"Dr. Abdul Samad Memorial Hospital","Seenu":"Addu Equatorial Hospital","Alifu Dhaalu":"Alifu Dhaalu Atoll Hospital"};
// Where each atoll hospital refers on to; south is source-backed, north is the nearest tertiary hospital
const TERTIARY_OF = {"Haa Alifu Atoll Hospital":{to:"Indira Gandhi Memorial Hospital (IGMH)",ok:false},"Kulhudhuffushi Regional Hospital":{to:"Indira Gandhi Memorial Hospital (IGMH)",ok:false},
  "Shaviyani Atoll Hospital":{to:"Indira Gandhi Memorial Hospital (IGMH)",ok:false},"Alifu Dhaalu Atoll Hospital":{to:"Indira Gandhi Memorial Hospital (IGMH)",ok:false},
  "Gaafu Alifu Atoll Hospital":{to:"Addu Equatorial Hospital",ok:true},"Dr. Abdul Samad Memorial Hospital":{to:"Addu Equatorial Hospital",ok:true}};

const HOSP = Object.fromEntries(LY["hospitals"].items.map(h=>[h.name,h]));
const isUnder = i => UNDER.atolls.includes(i.atoll);
const parentOf = id => { for(const [h,ids] of Object.entries(HC_PARENT)) if(ids.includes(id)) return {hosp:h,ok:true};
  const i=I[id]; const h=ATOLL_HOSP[i.atoll]; return h?{hosp:h,ok:false}:null; };

function hull(pts){ // monotone chain on [lon,lat]
  const p=pts.slice().sort((a,b)=>a[0]-b[0]||a[1]-b[1]); if(p.length<3) return p;
  const cr=(o,a,b)=>(a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0]);
  const lo=[],up=[];
  for(const q of p){while(lo.length>=2&&cr(lo[lo.length-2],lo[lo.length-1],q)<=0)lo.pop();lo.push(q);}
  for(const q of p.slice().reverse()){while(up.length>=2&&cr(up[up.length-2],up[up.length-1],q)<=0)up.pop();up.push(q);}
  return lo.slice(0,-1).concat(up.slice(0,-1));
}
const OVERLAYS = [
  {key:"u-periph", label:"Atolls listed as underserved (outlined)", sw:"periph"},
  {key:"u-trunk", label:"Freight trunk: Malé port → regional port", sw:"trunk"},
  {key:"u-feed", label:"Freight feeder: regional port → islands", sw:"feed"},
  {key:"u-emerg", label:"Emergency: island → atoll hospital", sw:"emerg"},
  {key:"u-emerg2", label:"Emergency: atoll hospital → tertiary hospital", sw:"emerg2"},
  {key:"u-focus", label:"Islands named in the document", sw:"focus"}
];
const OV = Object.fromEntries(OVERLAYS.map(o=>[o.key,o]));
OVERLAYS.forEach(o=>{o.on=false;o.group=L.layerGroup();});
const ll = p => [p.lat,p.lon];
// trunks: one per verified regional port
Object.values(FHUBS).forEach(h=>{
  L.polyline(curve(PORT,h,.05),{className:"trunk",interactive:false}).addTo(OV["u-trunk"].group);
});
UNDER.stats = {};
UNDER.atolls.forEach(a=>{
  const xs=ISL.filter(i=>i.atoll===a), cx=xs.reduce((s,i)=>s+i.lon,0)/xs.length, cy=xs.reduce((s,i)=>s+i.lat,0)/xs.length;
  const h=hull(xs.map(i=>[i.lon,i.lat])).map(([x,y])=>{const dx=x-cx,dy=y-cy,d=Math.hypot(dx,dy)||1;return [y+dy/d*.04,x+dx/d*.04];});
  L.polygon(h,{className:"periph",interactive:false}).addTo(OV["u-periph"].group);
  const fh=FHUBS[ATOLL_FHUB[a].hub], ok=ATOLL_FHUB[a].ok, hubIsle=I[fh.island];
  const spokes=xs.filter(i=>i.cat==="i"&&i!==hubIsle);
  spokes.forEach(i=>L.polyline([ll(fh),ll(i)],{className:"feeder"+(ok?"":" assumed"),interactive:false}).addTo(OV["u-feed"].group));
  const sd=spokes.map(i=>km(fh,i)), mx=sd.length?Math.max(...sd):0;
  UNDER.stats[a]={fh,ok,inh:xs.filter(i=>i.cat==="i").length,spokes:spokes.length,maxSpoke:mx,far:spokes[sd.indexOf(mx)],hosp:ATOLL_HOSP[a]};
});
// emergency tier: every inhabited island in the six atolls plus the named islands
const emergIsles = new Set([...ISL.filter(i=>isUnder(i)&&i.cat==="i").map(i=>i.id), ...UNDER.focus]);
let emergConfirmed=0, emergAssumed=0;
emergIsles.forEach(id=>{
  const i=I[id], p=parentOf(id); if(!p) return; const hosp=HOSP[p.hosp]; if(!hosp||hosp.isle===id) return;
  L.polyline([ll(i),ll(hosp)],{className:"emerg"+(p.ok?"":" assumed"),interactive:false}).addTo(OV["u-emerg"].group);
  p.ok?emergConfirmed++:emergAssumed++;
});
Object.entries(TERTIARY_OF).forEach(([h,t])=>{
  const a=HOSP[h], b=HOSP[t.to]; if(!a||!b) return;
  L.polyline(curve(a,b,.06),{className:"emerg2"+(t.ok?"":" assumed"),interactive:false}).addTo(OV["u-emerg2"].group);
});
UNDER.focus.forEach(id=>{
  const i=I[id];
  const m=L.circleMarker([i.lat,i.lon],{radius:10,className:"focus",bubblingMouseEvents:false});
  m.bindTooltip(i.name,{permanent:true,direction:"right",className:"under-label",interactive:false,offset:[8,0]});
  m.on("click",()=>select({kind:"isle",id},true));
  m.addTo(OV["u-focus"].group);
});
// ---------- underserved heat map: score per inhabited island ----------
const HEAT = {year:2026, pmode:"island", w:{health:30, transport:30, supply:20, pressure:20}};
const HEAT_PARTS = [
  {key:"health", label:"Health access", hint:"Distance to the nearest government hospital and to a tertiary hospital"},
  {key:"transport", label:"Boat connections", hint:"Trips to or from the island seen in the GPS data, 1 Aug 2025 (fewer = worse)"},
  {key:"supply", label:"Supply distance", hint:"Distance to the nearest regional port or Malé harbour, and to the nearest airport"},
  {key:"pressure", label:"Population", hint:""}
];
const NOT_AIRPORT = /^(Landing |Waterplane|Waterdrome|Amilla|MDNF)/;
const HEAT_ISLES = ISL.filter(i=>i.cat==="i");
const NO_FACILITY = HEAT_ISLES.filter(i=>!HC_ON[i.id]&&!LY["hospitals"].items.some(h=>h.isle===i.id&&/government/.test(h.extra.type)));
(function heatMetrics(){
  const govH = LY["hospitals"].items.filter(h=>!/private/i.test(h.extra.type||""));
  const tert = LY["hospitals"].items.filter(h=>/Tertiary hospital \(government\)/.test(h.extra.type||""));
  const ports = [PORT, ...Object.values(FHUBS)];
  const airs = LY["airports"].items.filter(a=>!NOT_AIRPORT.test(a.name));
  const minKm=(i,xs)=>Math.min(...xs.map(x=>km(i,x)));
  const trips={}; LINKS.forEach(l=>{ if(l.kind==="resort") return; trips[l.a]=(trips[l.a]||0)+l.trips; trips[l.b]=(trips[l.b]||0)+l.trips; });
  const areaKm2={}; HEAT_ISLES.forEach(i=>areaKm2[i.atoll]=(areaKm2[i.atoll]||0)+(i.area||0)/100);
  HEAT.areaKm2=areaKm2;
  HEAT_ISLES.forEach(i=>{ i.hm={hosp:minKm(i,govH), tert:minKm(i,tert), trips:trips[i.id]||0, port:minKm(i,ports), air:minKm(i,airs)}; });
})();
// scheduled weekly calls from the official timetables (shown, not scored: only Zones 1 and 6 are covered)
const DAYS_PER_WEEK = s => /Every day|Sun, Mon, Tue, Wed, Thu, Fri, Sat/.test(s)?7:/Sun, Mon, Tue, Wed, Thu, Sat/.test(s)?6:/Mon, Tue, Wed, Thu, Sat/.test(s)?5:/Sunday/.test(s)?1:7;
const SCHED = {};
ROUTES.filter(r=>r.type==="rtl").forEach(r=>{const n=DAYS_PER_WEEK(r.days);(r.legs||[]).forEach(([a,b])=>{SCHED[a]=(SCHED[a]||0)+n;SCHED[b]=(SCHED[b]||0)+n;});});
if(SCHED["s-meedhoo"]) SCHED["s-hulhudhoo"]=SCHED["s-meedhoo"];   // Hulhumeedhoo terminal serves both

function pctRank(vals){ // average-rank percentile 0..1
  const idx=vals.map((v,k)=>[v,k]).sort((a,b)=>a[0]-b[0]); const out=new Array(vals.length); let k=0;
  while(k<idx.length){let j=k;while(j+1<idx.length&&idx[j+1][0]===idx[k][0])j++;const r=(k+j)/2/(idx.length-1||1);for(let m=k;m<=j;m++)out[idx[m][1]]=r;k=j+1;}
  return out;
}
function density(atoll,year){const ys=D.pop.years, k=ys.indexOf(year); const p=(D.pop.maldivian[atoll]||[])[k]; const a=HEAT.areaKm2[atoll]; return p&&a?p/a:0;}
// island Maldivian residents: Census 2022 count, scaled by the atoll's projected growth from 2022 to the chosen year
function islandPop(i,year){const c=D.census[i.id]; if(!c) return null; const s=D.pop.maldivian[i.atoll], ys=D.pop.years;
  const k=ys.indexOf(year), k0=ys.indexOf(2022); return s&&k>=0&&k0>=0?c[1]*s[k]/s[k0]:c[1];}
function islandDensity(i,year){const c=D.census[i.id]; const p=islandPop(i,year); return p!=null&&c&&c[5]?p/(c[5]/100):null;}
const PRESSURE_MODES = {
  island:{label:"Island crowding", hint:"Maldivian residents per km² of the island's own land (Census 2022, grown at the atoll's projected rate). More crowded = higher."},
  small:{label:"Small population", hint:"Maldivian residents on the island (Census 2022, grown at the atoll's projected rate). Fewer people = higher, since small islands cost most to serve."},
  atoll:{label:"Atoll density (old method)", hint:"Maldivian residents per km² of inhabited land in the whole atoll (atoll projection). Every island in an atoll gets the same value."}
};
function pressureRaw(i){const y=HEAT.year;
  if(HEAT.pmode==="small"){const p=islandPop(i,y); return p==null?null:-p;}
  if(HEAT.pmode==="atoll") return density(i.atoll,y);
  return islandDensity(i,y);}
function pctRankNull(vals){const idx=vals.map((v,k)=>[v,k]).filter(x=>x[0]!=null); const r=pctRank(idx.map(x=>x[0])); const out=vals.map(()=>null); idx.forEach((x,j)=>out[x[1]]=r[j]); return out;}
function wscore(i,w){let s=0,ws=0; for(const k in w){ if(i.hc[k]==null) continue; s+=w[k]*i.hc[k]; ws+=w[k]; } return ws?s/ws:0;}
function computeHeat(){
  const I_=HEAT_ISLES;
  const pH=pctRank(I_.map(i=>i.hm.hosp)), pT=pctRank(I_.map(i=>i.hm.tert)), pTr=pctRank(I_.map(i=>i.hm.trips)),
        pP=pctRank(I_.map(i=>i.hm.port)), pA=pctRank(I_.map(i=>i.hm.air)), pD=pctRankNull(I_.map(pressureRaw));
  const W=HEAT.w;
  I_.forEach((i,k)=>{
    i.hc={health:(2*pH[k]+pT[k])/3, transport:1-pTr[k], supply:(pP[k]+pA[k])/2, pressure:pD[k]};
    i.hraw=100*wscore(i,W);
    i.hpop=islandPop(i,HEAT.year); i.hdenI=islandDensity(i,HEAT.year); i.hden=density(i.atoll,HEAT.year);
  });
  const lo=Math.min(...I_.map(i=>i.hraw)), hi=Math.max(...I_.map(i=>i.hraw));
  I_.forEach(i=>i.hscore=hi>lo?100*(i.hraw-lo)/(hi-lo):50);
  const order=I_.slice().sort((a,b)=>b.hscore-a.hscore); order.forEach((i,k)=>i.hrank=k+1);
  HEAT.order=order;
  // robustness: how often each island is in the top 10 under 500 random weightings (fixed seed)
  let seed=12345; const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
  const K=["health","transport","supply","pressure"], N=500; I_.forEach(i=>i.htop=0);
  for(let n=0;n<N;n++){const wv=K.map(()=>-Math.log(1-rnd())); const w=Object.fromEntries(K.map((k,j)=>[k,wv[j]]));
    I_.map(i=>[wscore(i,w),i]).sort((a,b)=>b[0]-a[0]).slice(0,10).forEach(([,i])=>i.htop++);}
  I_.forEach(i=>i.htop=100*i.htop/N);
  // evidence for the limits note
  const top=order.slice(0,10);
  HEAT.zeroTop=top.filter(i=>i.hm.trips===0).length; HEAT.zeroAll=I_.filter(i=>i.hm.trips===0).length;
  const w2={...W,transport:0};
  const alt=I_.slice().sort((a,b)=>wscore(b,w2)-wscore(a,w2)).slice(0,10);
  HEAT.keepNoTransport=top.filter(i=>alt.includes(i)).length;
  HEAT.topPeople=top.reduce((s,i)=>s+(i.hpop||0),0);
}
// red (most underserved) -> neutral -> blue (best served)
const HEAT_STOPS=[[0,[33,102,172]],[.2,[103,169,207]],[.4,[209,229,240]],[.5,[240,240,240]],[.6,[253,219,199]],[.8,[239,138,98]],[1,[178,24,43]]];
function heatColor(s){const t=Math.max(0,Math.min(1,s/100));let k=0;while(k<HEAT_STOPS.length-2&&t>HEAT_STOPS[k+1][0])k++;
  const [t0,c0]=HEAT_STOPS[k],[t1,c1]=HEAT_STOPS[k+1],f=(t-t0)/(t1-t0||1);return "rgb("+c0.map((v,j)=>Math.round(v+(c1[j]-v)*f)).join(",")+")";}
const HEAT_GRAD = "linear-gradient(90deg,"+HEAT_STOPS.map(([t,c])=>`rgb(${c.join(",")}) ${t*100}%`).join(",")+")";
map.createPane("heat"); map.getPane("heat").style.zIndex=450; map.getPane("heat").style.pointerEvents="none";
const heatR = L.svg({pane:"heat"});
const heatGroup = L.layerGroup();
HEAT_ISLES.forEach(i=>{
  i.halo=L.circleMarker([i.lat,i.lon],{renderer:heatR,pane:"heat",radius:14,stroke:false,fillOpacity:.3,interactive:false}).addTo(heatGroup);
  i.core=L.circleMarker([i.lat,i.lon],{renderer:heatR,pane:"heat",radius:5.5,weight:1.2,fillOpacity:.95,bubblingMouseEvents:false}).addTo(heatGroup);
  i.core.bindTooltip("",{className:"hover-tip",direction:"top",offset:[0,-4]});
  i.core.on("click",()=>select({kind:"isle",id:i.id},true));
});
function paintHeat(){
  const st=css("--dot-stroke");
  HEAT_ISLES.forEach(i=>{const c=heatColor(i.hscore);i.halo.setStyle({fillColor:c});i.core.setStyle({fillColor:c,color:st});
    i.core.setTooltipContent(`${esc(i.name)} · score ${Math.round(i.hscore)} · rank ${i.hrank} of ${HEAT_ISLES.length}`);});
}
computeHeat();

OVERLAYS.unshift({key:"u-heat",label:"Underserved heat map (score)",sw:"heat",on:false,group:heatGroup});
OV["u-heat"]=OVERLAYS[0];
function syncOverlays(){OVERLAYS.forEach(o=>{if(o.on&&!map.hasLayer(o.group))o.group.addTo(map);else if(!o.on&&map.hasLayer(o.group))o.group.remove();});
  if(OV["u-focus"].on) OV["u-focus"].group.eachLayer(l=>l.bringToFront&&l.bringToFront());}

function nearestIn(keys,i){let best=null,bd=1e9;keys.forEach(k=>LY[k].items.forEach(it=>{const d=km(i,it);if(d<bd){bd=d;best=it;}}));return best?{it:best,d:bd}:null;}

map.on("click",()=>{ if(state.sel) select(null); });
function zoomClasses(){const z=map.getZoom(),c=map.getContainer().classList;c.toggle("show-labels",z>=8.5);c.toggle("show-minor",z>=10.5);}
map.on("zoomend",zoomClasses);

// ---------- state ----------
const state={types:new Set(Object.keys(TYPES)),atoll:"all",sel:null,view:"routes",showUnv:false};
try{const saved=JSON.parse(localStorage.getItem("mbr-layers")||"null");if(Array.isArray(saved))LAYERS.forEach(l=>l.on=saved.includes(l.key));}catch(e){}
function saveLayers(){try{localStorage.setItem("mbr-layers",JSON.stringify(LAYERS.filter(l=>l.on).map(l=>l.key)));}catch(e){}}
const visRoute=r=>(!r.unv||state.showUnv)&&state.types.has(r.type)&&(state.atoll==="all"||r.stops.some(s=>I[s].atoll===state.atoll));
const inAtoll=it=>state.atoll==="all"||it.atoll===state.atoll;

function syncLayers(){
  LAYERS.forEach(l=>{
    if(!l.on&&!l.markers) return;
    if(!l.markers) l.markers=l.items.map(it=>makeMarker(l,it));
    l.items.forEach((it,k)=>{const m=l.markers[k],want=l.on&&inAtoll(it);
      if(want&&!map.hasLayer(m)) m.addTo(map); else if(!want&&map.hasLayer(m)) m.remove();});
  });
}

function render(){
  syncBase();
  syncGps();
  syncLayers();
  syncOverlays();
  const vis=new Set(ROUTES.filter(visRoute).map(r=>r.id));
  const sel=state.sel;
  const hot=new Set(), hotIsles=new Set();
  if(sel&&sel.kind==="route"){hot.add(sel.id);R[sel.id].stops.forEach(s=>hotIsles.add(s));}
  if(sel&&sel.kind==="isle"){hotIsles.add(sel.id);I[sel.id].routes.forEach(id=>{hot.add(id);R[id].stops.forEach(s=>hotIsles.add(s));});}
  const dimAll = !!sel && (sel.kind==="route"||hot.size>0);
  ROUTES.forEach(r=>{
    const lr=rLayers[r.id], on=vis.has(r.id)||hot.has(r.id);
    if(on){ if(!map.hasLayer(lr.line)){lr.line.addTo(map);lr.hit.addTo(map);} }
    else { lr.line.remove(); lr.hit.remove(); return; }
    const p=lr.line.getElement(); if(!p) return;
    p.classList.toggle("dim",dimAll&&!hot.has(r.id));
    p.classList.toggle("sel",hot.has(r.id));
    p.classList.toggle("flow",!!sel&&sel.kind==="route"&&sel.id===r.id&&r.type!=="road");
  });
  ROUTES.forEach(r=>{ if(hot.has(r.id)&&map.hasLayer(rLayers[r.id].line)) rLayers[r.id].line.bringToFront(); });
  ROUTE_ISLES.forEach(i=>{
    const m=iLayers[i.id];
    const on=hotIsles.has(i.id)||i.routes.some(id=>vis.has(id));
    if(on&&!map.hasLayer(m)) m.addTo(map); else if(!on&&map.hasLayer(m)) m.remove();
    if(!on) return;
    m.bringToFront();
    const el=m.getElement(); if(el){el.classList.toggle("dim",dimAll&&!hotIsles.has(i.id));el.classList.toggle("sel",!!sel&&sel.kind==="isle"&&sel.id===i.id);}
    const t=m.getTooltip()&&m.getTooltip().getElement(); if(t) t.classList.toggle("on",hotIsles.has(i.id));
  });
  const it=selItem();
  if(it&&!(it.kind==="isle"&&iLayers[it.id])){pin.setLatLng([it.lat,it.lon]);pin.addTo(map);pin.bringToFront();} else pin.remove();
  renderPanel(vis);
}
function selItem(){const s=state.sel;if(!s||s.kind==="link")return null;if(s.kind==="isle")return I[s.id];if(s.kind==="poi")return LY[s.layer].items[s.idx];return null;}

function select(s,fly){
  state.sel=s;
  if(s&&s.kind==="poi"&&!LY[s.layer].on){LY[s.layer].on=true;saveLayers();}
  if(s&&s.kind==="isle"){const l=LAYERS.find(l=>ISLCAT[l.key]===I[s.id].cat);if(l&&!l.on&&!I[s.id].routes.length){l.on=true;saveLayers();}}
  const it=selItem();
  if(it&&!inAtoll(it)){state.atoll="all";atollEl.value="all";}
  render();
  if(fly&&s){
    if(s.kind==="route") map.flyToBounds(L.latLngBounds(rLayers[s.id].pts),{padding:[50,50],maxZoom:11,duration:.6});
    else if(s.kind==="link"){map.flyToBounds(L.latLngBounds(LINKS[s.idx].path),{padding:[60,60],maxZoom:12,duration:.6});}
    else if(s.kind==="isle"&&I[s.id].routes.length){const i=I[s.id];const b=L.latLngBounds([[i.lat,i.lon]]);i.routes.forEach(r=>b.extend(L.latLngBounds(rLayers[r].pts)));map.flyToBounds(b,{padding:[50,50],maxZoom:11,duration:.6});}
    else map.flyTo([it.lat,it.lon],Math.max(map.getZoom(),12),{duration:.6});
  }
  document.getElementById("body").scrollTop=0;
  openPanel();
}

// ---------- panel ----------
const esc=s=>String(s??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const fmt=n=>n<10?n.toFixed(1):Math.round(n).toString();
const fmtKm=k=>k<1?Math.round(k*1000)+" m":fmt(k)+" km";
const posBlock=it=>`<span class="mono">${it.lat.toFixed(5)}, ${it.lon.toFixed(5)}</span><br><span class="mono">${dms(it.lat,"N","S")} ${dms(it.lon,"E","W")}</span>`;
function routeItem(r){return `<button class="item" data-route="${r.id}"><span class="sw ${r.type}"></span><span><span class="t">${esc(r.name.replace("Speedboat: ",""))}</span>${r.no?`<span class="no">#${r.no}</span>`:""}<span class="m">${r.unv?"Unverified · ":""}${r.stops.length} stops · ${fmt(nmi(r.km))} nmi</span></span></button>`;}
function placeItem(it,extra){const l=it.kind==="isle"?LAYERS.find(x=>ISLCAT[x.key]===it.cat):LY[it.layer];
  const data=it.kind==="isle"?`data-isle="${it.id}"`:`data-poi="${it.layer}:${it.idx}"`;
  return `<button class="item" ${data}><span class="dot" style="--c:var(${l.c})"></span><span><span class="t">${esc(it.name)}</span><span class="m">${esc(extra||"")}</span></span></button>`;}

function renderPanel(vis){
  const body=document.getElementById("body"), s=state.sel;
  const backBtn=`<button class="back" data-back>← ${state.view==="layers"?"Map layers":state.view==="under"?"Underserved islands":"All routes"}</button>`;
  if(!s&&state.view==="layers"){ body.innerHTML=layersHTML()+foot(); return; }
  if(!s&&state.view==="under"){ body.innerHTML=underHTML()+foot(); return; }
  if(!s){
    let h="";
    Object.keys(TYPES).forEach(t=>{
      const list=ROUTES.filter(r=>r.type===t&&vis.has(r.id)); if(!list.length) return;
      h+=`<div class="group"><div class="lbl">${TYPES[t].label} · ${list.length}</div>${list.map(routeItem).join("")}</div>`;
    });
    if(!h) h=`<p class="note">No boat routes ${state.atoll==="all"?"match these filters":"are mapped in "+esc(state.atoll)+" yet"}. Open Layers to see its islands, harbours and dive sites.</p>`;
    body.innerHTML=h+foot(); return;
  }
  if(s.kind==="link"){
    const l=LINKS[s.idx], A=I[l.a], B=I[l.b];
    const KIND={public:"Between inhabited islands / airport",resort:"Resort transfer",other:"Industrial or uninhabited island"};
    const rts=ROUTES.filter(r=>r.stops.some((x,k)=>k&&[r.stops[k-1],x].sort().join("|")===[l.a,l.b].sort().join("|")));
    body.innerHTML=`<div class="detail">${backBtn}
      <h2>${esc(A.name)} ↔ ${esc(B.name)}</h2>
      <span class="badge"><span class="sw gps"></span>Observed by GPS · ${KIND[l.kind]}</span>
      <dl class="facts"><dt>Trips</dt><dd class="mono">${l.trips} on 1 Aug 2025, by ${l.vessels} vessel${l.vessels>1?"s":""}</dd>
      <dt>Typical time</dt><dd class="mono">${fmt(l.med_min)} min · ${fmt(l.km)} km sailed</dd>
      <dt>Islands</dt><dd><button data-isle="${A.id}">${esc(A.name)}</button> (${esc(A.atoll)}) and <button data-isle="${B.id}">${esc(B.name)}</button> (${esc(B.atoll)})</dd></dl>
      <div class="lbl">Departures, Maldives time</div>
      <div class="deps">${l.deps.map(d=>`<span>${esc(d.replace("→","→ "+B.name).replace("←","→ "+A.name))}</span>`).join("")}</div>
      ${rts.length?`<div class="group"><div class="lbl">Mapped routes on this link</div>${rts.map(routeItem).join("")}</div>`:""}
      <p class="note">How this was derived from your GPS file (1,432 vessels, 1 August 2025): a vessel counts as stopped at an island when its reported speed is 2 or less and it is within the island's catchment (about 0.45 km plus the island's own radius) for at least 2 minutes or 3 pings. A trip is the move between stops at two different islands; trips with a gap of more than 30 minutes in the pings, or under 0.8 km, are dropped. The speed unit is not stated in the file. Device time is assumed to be UTC because vessel activity peaks at 01:00–12:00 on that clock (06:00–17:00 in the Maldives); times shown add 5 hours. The line follows one recorded trip. Vessel types are not in the data.</p></div>`+foot();
    return;
  }
  if(s.kind==="route"){
    const r=R[s.id];
    const stops=r.stops.map((id,k)=>{const i=I[id];const leg=k?`${fmt(nmi(km(I[r.stops[k-1]],i)))} nmi from ${esc(I[r.stops[k-1]].name)}`:"Departs";
      return `<li><button data-isle="${id}">${esc(i.name)}</button><span class="leg">${leg} · ${esc(i.atoll)}</span></li>`;}).join("");
    body.innerHTML=`<div class="detail">${backBtn}
      <h2>${esc(r.name.replace("Speedboat: ",""))}</h2>
      <span class="badge"><span class="sw ${r.type}"></span>${TYPES[r.type].label}${r.no?` · route ${r.no}`:""}</span>
      <dl class="facts"><dt>Distance</dt><dd class="mono">${fmt(nmi(r.km))} nmi · ${fmt(r.km)} km (straight-line legs)</dd>
      <dt>Runs</dt><dd>${esc(r.days)}</dd>${r.dur?`<dt>Time</dt><dd>${esc(r.dur)}</dd>`:""}
      ${r.effective?`<dt>Effective</dt><dd>${esc(r.effective)}</dd>`:""}<dt>Source</dt><dd>${r.unv?"<b>None</b>":esc(r.src||"")}</dd></dl>
      ${r.unv?`<p class="warn">${UNV}</p>`:""}
      <div class="lbl">Stops</div><ol class="stops">${stops}</ol>
      ${r.legs?ttHTML(r):""}
      ${r.note?`<p class="note">${esc(r.note)}</p>`:""}</div>`+foot();
    return;
  }
  if(s.kind==="isle"){
    const i=I[s.id], rs=i.routes.map(id=>R[id]);
    const near=nearby(i,3);
    body.innerHTML=`<div class="detail">${backBtn}
      <h2>${esc(i.name)}</h2>
      <span class="badge">${CATNAME[i.cat]}${i.cap?" · atoll capital":""}</span>
      <dl class="facts"><dt>Atoll</dt><dd>${esc(i.atoll)}</dd>
      ${i.area!=null?`<dt>Land area</dt><dd class="mono">${i.area>=100?(i.area/100).toFixed(1)+" km²":fmt(i.area)+" ha"}</dd>`:""}
      <dt>Position</dt><dd>${posBlock(i)}</dd>
      <dt>Source</dt><dd>MLSA island register</dd>
      <dt>Atlas</dt><dd><a class="ext" href="${ATLAS}/islands/${i.id}" target="_blank" rel="noopener">Open island page ↗</a></dd></dl>
      ${i.cat==="i"?heatIslandHTML(i):""}
      ${underCallout(i)}
      ${rs.length?`<div class="lbl">Boats that call here · ${rs.length}</div>${rs.map(routeItem).join("")}`:`<p class="note">No boat routes on this map call here yet.</p>`}
      ${observedHTML(i)}
      ${i.cat==="i"?supplyHTML(i):""}
      ${near.length?`<div class="group"><div class="lbl">Within 3 km · ${near.length}</div>${near.slice(0,12).map(n=>placeItem(n.it,`${n.it.kind==="isle"?CATNAME[n.it.cat]:singular[n.it.layer]} · ${fmtKm(n.d)}`)).join("")}${near.length>12?`<p class="note">and ${near.length-12} more nearby.</p>`:""}</div>`:""}
      </div>`+foot();
    return;
  }
  const it=LY[s.layer].items[s.idx], l=LY[s.layer], x=it.extra, home=I[it.isle];
  let more="";
  if(s.layer==="fads"){
    more=`${x.no?`<dt>FAD number</dt><dd class="mono">${esc(x.no)}</dd>`:""}${x.type?`<dt>Type</dt><dd>${esc(x.type)}</dd>`:""}
      ${x.home?`<dt>Home island</dt><dd>${esc(x.home)}</dd>`:""}${x.state?`<dt>Status</dt><dd>${esc(x.state)}</dd>`:""}
      ${x.dm?`<dt>Register</dt><dd class="mono">${esc(x.dm)}</dd>`:""}`;
  }
  if(s.layer==="health-centres"){
    more=`<dt>Grade</dt><dd>${esc(x.grade)}</dd><dt>Registration</dt><dd class="mono">${esc(x.reg)}</dd>
      <dt>Island match</dt><dd>${x.how==="exact"?"Island named in the facility's name":x.how==="joined-island"?"The facility is named for Hulhumeedhoo, which covers both Meedhoo and Hulhudhoo":"Island name in the facility differs in spelling from the register; matched to the closest name"}</dd>`;
  }
  if(s.layer==="hospitals"){
    const t=TERTIARY_OF[it.name];
    more=`<dt>Type</dt><dd>${esc(x.type)}</dd><dt>Status</dt><dd>${esc(x.status)}</dd><dt>Registration</dt><dd class="mono">${esc(x.reg)}</dd>${t?`<dt>Refers to</dt><dd><button data-poi="hospitals:${HOSP[t.to].idx}">${esc(t.to)}</button>${t.ok?"":" <span class=\"cite\">(assumed, nearest tertiary)</span>"}</dd>`:""}`;
    const kids=Object.keys(HC_PARENT).includes(it.name)?HC_PARENT[it.name]:[];
    if(kids.length) more+=`<dt>Health centres</dt><dd>${kids.length} islands list this as their parent hospital in the register</dd>`;
  }
  let units="";
  if(s.layer==="ice-plants"&&x.units&&x.units.length){
    units=`<div class="lbl">Registered plants · ${x.units.length}</div><div class="tw"><table class="units"><thead><tr><th>Operator</th><th style="text-align:right">Capacity</th><th>Phone</th></tr></thead><tbody>${
      x.units.map(u=>`<tr><td>${esc(u.op)}</td><td class="num">${fmt(u.cap)}</td><td class="mono">${esc(u.tel)}</td></tr>`).join("")}</tbody></table></div>
      <p class="note">Capacity as listed in the fisheries register, ${fmt(x.total)} in total at this site.</p>
      ${x.moved?`<p class="warn">The register's own coordinates put this plant about ${x.moved} km away, out at sea. The atlas places it on the island named instead.</p>`:""}`;
  }
  const src = GROUPS[l.group].src;
  body.innerHTML=`<div class="detail">${backBtn}
    <h2>${esc(it.name)}</h2>${x.dv?`<p class="dv" lang="dv" dir="rtl">${esc(x.dv)}</p>`:""}
    <span class="badge"><span class="dot" style="--c:var(${l.c})"></span>${singular[l.key]}</span>
    <dl class="facts"><dt>Atoll</dt><dd>${esc(it.atoll)}</dd>
    ${more}
    <dt>Position</dt><dd>${posBlock(it)}</dd>
    ${home?`<dt>Nearest island</dt><dd><button data-isle="${home.id}">${esc(home.name)}</button> · ${fmtKm(it.dist)}</dd>`:""}
    <dt>Source</dt><dd>${esc(src)}</dd>
    ${it.href?`<dt>Atlas</dt><dd><a class="ext" href="${ATLAS}${esc(it.href)}" target="_blank" rel="noopener">Open on Dhuveli Atlas ↗</a></dd>`:`<dt>Placement</dt><dd class="cite">${esc(x.placed||"")}. Shown at the island's register position; the exact building is not published.${x.nudged?" Nudged east (about 280 m per extra facility) so hospitals on the same island can be told apart.":""}</dd>`}</dl>
    ${units}</div>`+foot();
}
const VERIFY = [
  {claim:"About 41% of people live in Malé.", status:"ok", note:"Stated in the paper the summary cites.", src:["eya23"]},
  {claim:"About 80 islands need emergency water in dry seasons.", status:"part", note:"True, but not from the paper cited. Acciarri et al. give no number. UNDP reports more than 81 islands have requested emergency water since 2005.", src:["undp19","acciarri21"]},
  {claim:"Sea ambulances and a four-tier referral system.", status:"ok", note:"Both in Eya et al., and Aboobakuru also describes four tiers. The Ministry of Health's own site describes three tiers.", src:["eya23","aboo14","mohTiers"]},
  {claim:"Haa Alifu, Haa Dhaalu, Shaviyani, Gaafu Alifu, Gaafu Dhaalu and Addu are the underserved periphery.", status:"no", note:"No cited source names these six. Eya et al. speak only of “the northern and southern regions”. Farhath et al. is a mangrove survey that does not discuss services. Duvat & Magnan call the far north and south a “less-developed periphery” without listing atolls. Rishan et al. could not be checked.", src:["eya23","farhath25","duvat19"]},
  {claim:"Haa Alifu–Noonu and Seenu were made Regional Development Poles in the 1990s.", status:"ok", note:"Figure 2 caption, word for word. The same caption says the far atolls now show “rapid socio-economic development”.", src:["duvat19"]},
  {claim:"Filladhoo, Uligamu and Mandhoo are vulnerable to staple-goods shortages.", status:"no", note:"None of the cited sources that could be checked mention these islands or staple goods. Duvat (2020) could not be accessed.", src:["hinkel23","aboo14","duvat19"]},
  {claim:"Mandhoo is in Alifu Dhaalu, a central atoll.", status:"ok", note:"The island register places it in Alifu Dhaalu, which Duvat & Magnan's Figure 2 classes with the central atolls, not the far periphery.", src:["register","duvat19"]},
  {claim:"Feeder sailings are infrequent (citing Mandaku & Rasyid 2023).", status:"no", note:"That paper studies Maluku province in Indonesia, as its own title says, not the Maldives.", src:["doc"]}
];
const STATUS = {ok:["Verified","--l-prot"], part:["Partly","--l-light"], no:["Not supported","--under"]};

function ttHTML(r){
  const rows=r.legs.map(([a,b,d,t])=>{const lk=linkFor(a,b);return `<tr><td>${esc(shortName(a))}</td><td>${esc(d||"")}</td><td>${esc(shortName(b))}</td><td>${esc(t||"")}</td><td class="${lk?"seen":""}">${lk?lk.trips:"–"}</td></tr>`;}).join("");
  return `<div class="group"><div class="lbl">Timetable</div><div class="tw"><table class="tt"><thead><tr><th>From</th><th>Departs</th><th>To</th><th>Arrives</th><th>GPS trips</th></tr></thead><tbody>${rows}</tbody></table></div>
    <p class="note">${r.gpsLegs} of ${r.stops.length-1} legs match an island pair that some tracked vessel sailed on 1 Aug 2025; those legs are drawn along that vessel's GPS track, which may not be this ferry. The rest are schematic. ${r.zone===1?"The timetable dates from 2022 and may have changed since.":"Hulhumeedhoo terminal is on Meedhoo, which is joined to Hulhudhoo."}</p></div>`;
}
function observedHTML(i){
  const ls=LINKS.filter(l=>l.a===i.id||l.b===i.id).sort((a,b)=>b.trips-a.trips);
  if(!ls.length) return `<div class="group"><div class="lbl">Observed sailings</div><p class="note">No tracked vessel sailed to or from here on 1 Aug 2025.</p></div>`;
  return `<div class="group"><div class="lbl">Observed sailings, 1 Aug 2025 · ${ls.length}</div>${ls.slice(0,10).map(l=>{const o=l.a===i.id?l.b:l.a;
    return `<button class="item" data-link="${l.idx}"><span class="sw gps" style="margin-top:10px;flex:none"></span><span><span class="t">${esc(shortName(o))}</span><span class="m">${l.trips} trip${l.trips>1?"s":""} · ${l.vessels} vessel${l.vessels>1?"s":""} · ${fmt(l.med_min)} min</span></span></button>`;}).join("")}${ls.length>10?`<p class="note">and ${ls.length-10} more.</p>`:""}</div>`;
}
function underCallout(i){
  const focus=UNDER.focus.includes(i.id), under=isUnder(i);
  if(!focus&&!under) return "";
  let h=`<div class="callout"><div class="lbl">Underserved island</div>`;
  if(under) h+=`<p>Your document lists ${esc(i.atoll)} among the underserved ${UNDER.north.includes(i.atoll)?"northern":"southern"} atolls, with medical specialist shortages and economic isolation. Its cited papers do not name this atoll: Eya et al. refer only to the northern and southern regions in general.</p><p class="cite">${cite("eya23")}</p>`;
  if(i.atoll==="Haa Alifu"||i.atoll==="Seenu") h+=`<p>Duvat &amp; Magnan say ${i.atoll==="Seenu"?"Seenu":"the Haa Alifu–Noonu region"} was made a Regional Development Pole in the 1990s and has had more investment than other far atolls. Verified.</p><p class="cite">${cite("duvat19")}</p>`;
  if(focus) h+=`<p>Your document names this island as vulnerable to staple-goods shortages. None of the sources it cites that could be checked mention the island, so treat this as unverified.</p><p class="cite">${cite("hinkel23","aboo14","duvat19")}</p>`;
  if(i.id==="adh-mandhoo") h+=`<p>Mandhoo is in Alifu Dhaalu, a central atoll, not the far periphery. Verified.</p><p class="cite">${cite("register","duvat19")}</p>`;
  return h+`</div>`;
}
function supplyHTML(i){
  const fhk=ATOLL_FHUB[i.atoll], fh=fhk?FHUBS[fhk.hub]:null;
  const harb=nearestIn(["harbours","ferry-terminals"],i), air=nearestIn(["airports"],i), ice=nearestIn(["ice-plants"],i);
  const link=n=>n?`<button data-poi="${n.it.layer}:${n.it.idx}">${esc(n.it.name)}</button> · ${fmtKm(n.d)}`:"None mapped";
  const p=parentOf(i.id), hosp=p?HOSP[p.hosp]:null;
  const nearestHosp=nearestIn(["hospitals"],i);
  const dPort=km(PORT,i);
  return `<div class="group"><div class="lbl">Access and supply</div><dl class="facts">
    <dt>From Malé port</dt><dd class="mono">${fmt(nmi(dPort))} nmi · ${fmt(dPort)} km</dd>
    ${fh?`<dt>Regional port</dt><dd>${esc(fh.name)} · ${fmtKm(km(fh,i))}${fhk.ok?"":" <span class=\"cite\">(assumed)</span>"}</dd>`:""}
    <dt>On the island</dt><dd>${(()=>{const h=LY["hospitals"].items.filter(x=>x.isle===i.id);const c=HC_ON[i.id];
      return h.length?h.map(x=>`<button data-poi="hospitals:${x.idx}">${esc(x.name)}</button>`).join(", "):c?`Government health centre (${esc(c[2])})`:"<b>No government health facility registered</b>";})()}</dd>
    <dt>Referral hospital</dt><dd>${hosp&&hosp.isle!==i.id?`<button data-poi="hospitals:${hosp.idx}">${esc(hosp.name)}</button> · ${fmtKm(km(hosp,i))}${p.ok?" <span class=\"cite\">(per register)</span>":" <span class=\"cite\">(same atoll, assumed)</span>"}`:hosp?`This island has ${esc(hosp.name)}`:nearestHosp?(nearestHosp.d<0.5?"On this island":`Nearest: ${link(nearestHosp)}`):"None mapped"}</dd>
    <dt>Nearest harbour</dt><dd>${link(harb)}</dd>
    <dt>Nearest airport</dt><dd>${link(air)}</dd>
    <dt>Nearest ice plant</dt><dd>${link(ice)}</dd></dl>
    <p class="note">Straight-line distances between register positions. Malé port is MPL Dock, the Commercial Harbour. Harbours and airports come from OpenStreetMap, which is incomplete in the outer atolls. The Ministry of Health says every inhabited island has a health facility; its register lists none for ${NO_FACILITY.length} inhabited islands (${NO_FACILITY.map(x=>esc(x.name)).join(", ")}).</p></div>`;
}
function heatListHTML(){
  const row=i=>`<button class="item" data-isle="${i.id}"><span class="hdot" style="background:${heatColor(i.hscore)}"></span><span><span class="t">${esc(i.name)}</span><span class="m">${esc(i.atoll)} · score ${Math.round(i.hscore)} · rank ${i.hrank} · ${i.hpop!=null?Math.round(i.hpop).toLocaleString()+" Maldivian residents":"no census count"} · top 10 in ${Math.round(i.htop)}% of random weightings</span></span></button>`;
  const o=HEAT.order;
  return `<div class="group"><div class="lbl">Most underserved · top 10</div>${o.slice(0,10).map(row).join("")}</div>
    <div class="group"><div class="lbl">Best served · top 5</div>${o.slice(-5).reverse().map(row).join("")}</div>`;
}
function heatHTML(){
  return `<div class="heatbox"><div class="lbl">Underserved heat map · ${HEAT_ISLES.length} inhabited islands</div>
    <div class="legend"><span>Best served</span><div class="grad" style="background:${HEAT_GRAD}"></div><span>Most underserved</span></div>
    <label class="lyr" for="ov-u-heat-2"><input type="checkbox" id="ov-u-heat-2" data-overlay="u-heat" ${OV["u-heat"].on?"checked":""}>Show the heat map</label>
    <div class="yrow"><label for="heat-pmode">Population counts as</label><select id="heat-pmode">${Object.entries(PRESSURE_MODES).map(([k,m])=>`<option value="${k}" ${k===HEAT.pmode?"selected":""}>${m.label}</option>`).join("")}</select></div>
    <div class="yrow"><label for="heat-year">Population year</label><select id="heat-year">${D.pop.years.map(y=>`<option ${y===HEAT.year?"selected":""}>${y}</option>`).join("")}</select></div>
    ${HEAT_PARTS.map(p=>`<div class="wrow"><label for="hw-${p.key}">${p.label}</label><span class="wv" id="hwv-${p.key}">${HEAT.w[p.key]}%</span>
      <input type="range" id="hw-${p.key}" data-hw="${p.key}" min="0" max="60" step="5" value="${HEAT.w[p.key]}"><span class="m" ${p.key==="pressure"?'id="pmode-hint"':""}>${p.key==="pressure"?PRESSURE_MODES[HEAT.pmode].hint:p.hint}</span></div>`).join("")}
    <p class="note">Each part is ranked across all inhabited islands, weighted by the sliders, then scaled so the best-served island is 0 and the most underserved is 100. The weights are a judgement; change them to test how robust a ranking is.</p></div>
    <div id="heat-list">${heatListHTML()}</div>
    <div id="heat-evidence">${heatEvidenceHTML()}</div>
    <p class="note">Limits: island population is the Census 2022 count (MBS); for other years it is grown at the atoll's projected rate, which assumes islands grow in step with their atoll. Mantaafushi has no census count and is scored on the other three parts. Boat connections come from one day of GPS on 1,432 tracked vessels, which under-counts islands those boats rarely visit. Timetables cover only Zones 1 and 6, so they are shown on each island but not scored. Distances are straight lines. Hospitals come from the full Ministry of Health register; ${D.moh.unplaced.length} with no stated island (${D.moh.unplaced.map(esc).join(", ")}) are not placed, and the Vaavu Atoll Hospital's island is inferred.</p>`;
}
function heatEvidenceHTML(){
  return `<p class="warn">How solid is this ranking? ${HEAT.zeroTop} of the current top 10 had no GPS-observed trips (as did ${HEAT.zeroAll} of ${HEAT_ISLES.length} inhabited islands, which tie on that part). With boat connections set to 0, ${HEAT.keepNoTransport} of these 10 stay in the top 10. Across 500 random weightings, the most stable island is in the top 10 ${Math.round(Math.max(...HEAT_ISLES.map(i=>i.htop)))}% of the time. The current top 10 islands have about ${Math.round(HEAT.topPeople).toLocaleString()} Maldivian residents between them. Treat the order as indicative, not a measured result.</p>`;
}
function heatIslandHTML(i){
  if(!i.hc) return "";
  const W=HEAT.w, m=i.hm, sch=SCHED[i.id];
  const part=(k,label,txt)=>`<div class="bar"><span>${label}</span><span class="mono">${Math.round(i.hc[k]*100)}</span><div class="track"><div class="fill" style="width:${Math.max(3,i.hc[k]*100)}%;background:${heatColor(i.hc[k]*100)}"></div></div><span class="m">${txt}</span></div>`;
  return `<div class="group"><div class="lbl">Underserved score</div>
    <div class="score"><b style="color:${heatColor(i.hscore)}">${Math.round(i.hscore)}</b><span>rank ${i.hrank} of ${HEAT_ISLES.length} inhabited islands (1 = most underserved); in the top 10 under ${Math.round(i.htop)}% of 500 random weightings</span></div>
    <div class="bars">
      ${part("health","Health access",`${fmtKm(m.hosp)} to the nearest government hospital, ${fmtKm(m.tert)} to a tertiary hospital`)}
      ${part("transport","Boat connections",`${m.trips} GPS-observed trip${m.trips===1?"":"s"} on 1 Aug 2025${sch?` · ${sch} scheduled RTL calls a week`:""}`)}
      ${part("supply","Supply distance",`${fmtKm(m.port)} to the nearest regional port or Malé harbour, ${fmtKm(m.air)} to the nearest airport`)}
      ${i.hc.pressure==null?`<div class="bar"><span>Population</span><span class="mono">–</span><span class="m">No Census 2022 count for this island, so this part is left out and the other three are re-weighted.</span></div>`:
        part("pressure","Population ("+PRESSURE_MODES[HEAT.pmode].label.toLowerCase()+")",
          HEAT.pmode==="atoll"?`${Math.round(i.hden).toLocaleString()} Maldivian residents per km² of inhabited land in ${esc(i.atoll)} (${HEAT.year})`
          :`${Math.round(i.hpop).toLocaleString()} Maldivian residents (${HEAT.year}${HEAT.year===2022?", Census":", from Census 2022 grown at the atoll's projected rate"}) on ${fmt(D.census[i.id][5]/100)} km², ${Math.round(i.hdenI).toLocaleString()} per km²`)}
    </div><p class="note">Part scores are 0–100 percentiles among inhabited islands (higher = worse). Weights: health ${W.health}, boats ${W.transport}, supply ${W.supply}, pressure ${W.pressure}.</p></div>`;
}
function underHTML(){
  const tiers=`<ol class="tiers">
    <li><span class="tsw"></span><span><span class="t">Freight trunk</span><span class="m">Malé Commercial Harbour to three regional ports, by coastal cargo ship and domestic air freight.</span></span></li>
    <li><span class="tsw feed"></span><span><span class="t">Freight feeder</span><span class="m">Regional port out to each inhabited island, by inter-island ferry and cargo dhoni. Faint lines are assumed links.</span></span></li>
    <li><span class="tsw emerg"></span><span><span class="t">Emergency, first leg</span><span class="m">Island health centre to its atoll or regional hospital, by sea ambulance. Solid where the Ministry register names the parent hospital (${emergConfirmed} islands), dashed where the map assumes the hospital in the same atoll (${emergAssumed}).</span></span></li>
    <li><span class="tsw emerg2"></span><span><span class="t">Emergency, second leg</span><span class="m">Atoll hospital to a tertiary hospital. Southern atolls to Addu Equatorial Hospital, which state media calls a key referral hospital for "other southern atolls" (it does not name them). Northern atolls to IGMH in Malé, assumed as the nearest tertiary hospital.</span></span></li></ol>
    <p class="cite">${cite("eya23","mohTiers","aeh","maaharaa")}</p>`;
  const hubs=Object.values(FHUBS).map(h=>`<div class="hub"><div class="t">${esc(h.name)}</div><div class="m">${esc(h.role)} ${esc(h.status)}.</div><div class="cite">${cite(...h.src)}</div></div>`).join("");
  const rows=UNDER.atolls.map(a=>{const s=UNDER.stats[a];
    return `<button class="item" data-uatoll="${esc(a)}"><span class="tsw" style="width:18px;margin-top:10px;flex:none"></span><span><span class="t">${esc(a)}</span><span class="m">Port ${esc(s.fh.name.replace(/ \(.*\)/,""))}${s.ok?"":" (assumed)"} · hospital ${esc(s.hosp)} · ${s.inh} inhabited islands, farthest ${esc(s.far.name)} ${fmt(s.maxSpoke)} km from the port</span></span></button>`;}).join("");
  const named=UNDER.focus.map(id=>{const i=I[id];return `<button class="item" data-isle="${id}"><span class="dot" style="--c:var(--under)"></span><span><span class="t">${esc(i.name)}</span><span class="m">${esc(i.atoll)} · ${fmt(nmi(km(PORT,i)))} nmi from Malé port</span></span></button>`;}).join("");
  const ver=VERIFY.map(v=>`<li><span class="vs" style="--c:var(${STATUS[v.status][1]})">${STATUS[v.status][0]}</span><span><span class="t">${esc(v.claim)}</span><span class="m">${esc(v.note)}</span><span class="cite">${cite(...v.src)}</span></span></li>`).join("");
  return `<div class="detail"><h2>Underserved islands</h2>${heatHTML()}
    <p class="intro">The outer atolls depend on a hub-and-spoke chain that starts at Malé. Cargo and patients pass through regional ports and hospitals before reaching the smaller islands.</p>
    <div class="stat"><div><b>41%</b><span>of people live in Malé</span></div><div><b>81+</b><span>islands have needed emergency water since 2005</span></div><div><b>2 + 1</b><span>regional ports operating, plus Thinadhoo under development</span></div></div>
    <div class="group"><div class="lbl">How essentials and patients travel</div>${tiers}</div>
    <div class="group"><div class="lbl">Regional ports · verified</div><div class="hubs">${hubs}</div></div>
    <div class="group"><div class="lbl">Atolls the document lists · ${UNDER.atolls.length}</div>${rows}</div>
    <div class="group"><div class="lbl">Islands the document names · 3</div>${named}</div>
    <div class="group"><div class="lbl">What the sources support</div><ul class="verify">${ver}</ul></div>
    <p class="note">Health facilities are not in OpenStreetMap's data on the atlas, so hospitals come from the Ministry of Health register and sit at their island's register position. Sea ambulance stations are not published, so the emergency lines show who refers to whom, not boat routes.</p></div>`;
}

function nearby(i,maxKm){
  const out=[];
  LAYERS.forEach(l=>l.items.forEach(it=>{ if(it===i) return; if(Math.abs(it.lat-i.lat)>.03||Math.abs(it.lon-i.lon)>.03) return;
    const d=km(i,it); if(d<=maxKm) out.push({it,d}); }));
  return out.sort((a,b)=>a.d-b.d);
}
function layersHTML(){
  let h=`<div class="lgroup"><div class="lbl">Base map<span class="src">MLSA survey outlines</span></div>${BASE.map(b=>
    `<label class="lyr" for="base-${b.key}"><input type="checkbox" id="base-${b.key}" data-base="${b.key}" ${b.on?"checked":""}><span class="dot" style="--c:var(${b.key==="atoll"?"--atoll-fill":b.key==="reef"?"--reef":b.key==="lagoon"?"--lagoon":"--pa-edge"});border-radius:3px"></span>${b.label}<span class="n">${b.count}</span></label>`).join("")}</div>`;
  Object.entries(GROUPS).forEach(([g,meta])=>{
    const ls=LAYERS.filter(l=>l.group===g);
    h+=`<div class="lgroup"><div class="lbl">${meta.label}<span class="src">${esc(meta.src)}</span></div>${ls.map(l=>{
      const n=l.items.filter(inAtoll).length;
      return `<label class="lyr" for="lyr-${l.key}"><input type="checkbox" id="lyr-${l.key}" data-layer="${l.key}" ${l.on?"checked":""}><span class="dot" style="--c:var(${l.c})"></span>${l.label}<span class="n">${n}</span></label>`;}).join("")}</div>`;
  });
  h+=`<div class="lgroup"><div class="lbl">Observed sailings<span class="src">Your GPS file, 1 Aug 2025</span></div>${GPSL.map(g=>
    `<label class="lyr" for="gps-${g.key}"><input type="checkbox" id="gps-${g.key}" data-gps="${g.key}" ${g.on?"checked":""}><span class="sw gps" style="${g.key==="resort"?"border-top-style:dashed":""}"></span>${g.label}<span class="n">${g.count}</span></label>`).join("")}</div>`;
  h+=`<div class="lgroup"><div class="lbl">Underserved islands<span class="src">Your document, checked against public sources</span></div>${OVERLAYS.map(o=>
    `<label class="lyr" for="ov-${o.key}"><input type="checkbox" id="ov-${o.key}" data-overlay="${o.key}" ${o.on?"checked":""}>${o.sw==="heat"?`<span style="width:18px;height:8px;border-radius:4px;flex:none;background:${HEAT_GRAD}"></span>`:""}<span ${o.sw==="heat"?"hidden ":""}class="tsw ${["feed","emerg","emerg2"].includes(o.sw)?o.sw:""}" style="${o.sw==="focus"||o.sw==="periph"?"width:12px;height:12px;border:2px "+(o.sw==="periph"?"dashed":"solid")+" var(--under);border-radius:"+(o.sw==="focus"?"50%":"3px")+";margin:0":"width:18px;margin:0"}"></span>${o.label}<span class="n">${o.group.getLayers().length}</span></label>`).join("")}</div>`;
  return `<div class="lyr-actions"><button class="linkbtn" data-all="on">Show all</button><button class="linkbtn" data-all="off">Hide all</button><button class="linkbtn" data-all="default">Reset</button></div>${h}
    <p class="note">Counts follow the atoll filter. Click any point on the map for its details.</p>`;
}
function foot(){return `<div class="foot"><p>Islands, and the reef, lagoon and protected-area outlines: Maldives Land and Survey Authority survey. Harbours, dive sites, lights and airports: © OpenStreetMap contributors (ODbL). FADs and ice plants: Maldives Fisheries Information System. Hospitals and health centres: Ministry of Health register of health establishments (586 entries, supplied by you). All except hospitals via the <a class="ext" href="${ATLAS}/about" target="_blank" rel="noopener">Dhuveli Atlas</a>, data of 17 October 2026.</p>
<p>RTL routes: MTCC ferry schedules (Zone 1, 2022; Zone 6, 2026). Other routes cite their source on the route page; routes without a source are marked Unverified and hidden unless you turn them on. Population: island counts from MBS Census 2022 (Island Level Indicator Sheet; Malé City from Statistical Yearbook 2024 Table 1.5) and atoll projections 2022–2062 (your files). Observed sailings: GPS from 1,432 tracked vessels on 1 August 2025. Non-RTL routes are drawn as schematic lines. Timetables change, so confirm with the operator before you travel.</p><p>Not for navigation.</p></div>`;}

const bodyEl=document.getElementById("body");
bodyEl.addEventListener("click",e=>{
  const r=e.target.closest("[data-route]"), i=e.target.closest("[data-isle]"), p=e.target.closest("[data-poi]"), b=e.target.closest("[data-back]"), all=e.target.closest("[data-all]"), ua=e.target.closest("[data-uatoll]");
  if(ua){const a=ua.dataset.uatoll;state.atoll=a;atollEl.value=a;OVERLAYS.forEach(o=>o.on=true);LY.inhabited.on=true;saveLayers();render();
    map.flyToBounds(L.latLngBounds(ISL.filter(x=>x.atoll===a).map(x=>[x.lat,x.lon])),{padding:[40,40],maxZoom:12,duration:.6});return;}
  if(all) OVERLAYS.forEach(o=>o.on=all.dataset.all==="on");
  const lk=e.target.closest("[data-link]"); if(lk){select({kind:"link",idx:+lk.dataset.link},true);return;}
  if(r) select({kind:"route",id:r.dataset.route},true);
  else if(i) select({kind:"isle",id:i.dataset.isle},true);
  else if(p){const [layer,idx]=p.dataset.poi.split(":");select({kind:"poi",layer,idx:+idx},true);}
  else if(b) select(null);
  else if(all){const v=all.dataset.all;LAYERS.forEach(l=>l.on=v==="on"?true:v==="off"?false:["inhabited","ferry-terminals","hospitals"].includes(l.key));saveLayers();render();}
});
function refreshHeat(){computeHeat();paintHeat();const hl=document.getElementById("heat-list");if(hl)hl.innerHTML=heatListHTML();const he=document.getElementById("heat-evidence");if(he)he.innerHTML=heatEvidenceHTML();}
bodyEl.addEventListener("input",e=>{const r=e.target.closest("[data-hw]");if(!r)return;HEAT.w[r.dataset.hw]=+r.value;
  const v=document.getElementById("hwv-"+r.dataset.hw);if(v)v.textContent=r.value+"%";refreshHeat();});
bodyEl.addEventListener("change",e=>{
  if(e.target.id==="heat-year"){HEAT.year=+e.target.value;refreshHeat();return;}
  if(e.target.id==="heat-pmode"){HEAT.pmode=e.target.value;const h=document.getElementById("pmode-hint");if(h)h.textContent=PRESSURE_MODES[HEAT.pmode].hint;refreshHeat();return;}
  const o=e.target.closest("[data-overlay]"); if(o){OV[o.dataset.overlay].on=o.checked;render();return;}
  const bb=e.target.closest("[data-base]"); if(bb){BS[bb.dataset.base].on=bb.checked;render();return;}
  const gg=e.target.closest("[data-gps]"); if(gg){GL[gg.dataset.gps].on=gg.checked;render();return;}
  const c=e.target.closest("[data-layer]");if(!c)return;LY[c.dataset.layer].on=c.checked;saveLayers();render();});

// tabs
const tabR=document.getElementById("tab-routes"), tabL=document.getElementById("tab-layers"), tabU=document.getElementById("tab-under");
function setView(v){state.view=v;tabR.setAttribute("aria-selected",v==="routes");tabL.setAttribute("aria-selected",v==="layers");tabU.setAttribute("aria-selected",v==="under");state.sel=null;
  if(v==="under"){
    if(!OVERLAYS.some(o=>o.on)) ["u-heat","u-periph","u-focus"].forEach(k=>OV[k].on=true);
    if(!LY.inhabited.on){LY.inhabited.on=true;saveLayers();}
    state.atoll="all";atollEl.value="all";
    render();openPanel();
    map.flyToBounds(L.latLngBounds(ISL.map(i=>[i.lat,i.lon])),{padding:[20,20],duration:.6});
    return;
  }
  render();openPanel();}
tabR.addEventListener("click",()=>setView("routes"));
tabL.addEventListener("click",()=>setView("layers"));
tabU.addEventListener("click",()=>setView("under"));

// filters
const typesEl=document.getElementById("types"), typesDd=document.getElementById("typesdd"), typesSum=document.getElementById("types-sum");
typesEl.innerHTML=Object.entries(TYPES).map(([k,t])=>`<label class="dd-opt"><input type="checkbox" data-type="${k}" checked><span class="sw ${k}"></span>${t.short}</label>`).join("")
  +`<div class="dd-sep"></div><label class="dd-opt" title="Routes added without a source"><input type="checkbox" data-unv="1"><span>Unverified (${ROUTES.filter(r=>r.unv).length})</span></label>`;
function updateTypesLabel(){
  const n=state.types.size,total=Object.keys(TYPES).length;
  let t=n===total?"All route types":n===0?"No route types":n+" of "+total+" route types";
  if(state.showUnv) t+=" + unverified";
  typesSum.textContent=t;
}
typesEl.addEventListener("change",e=>{
  const c=e.target;
  if(c.dataset.unv) state.showUnv=c.checked;
  else if(c.dataset.type) c.checked?state.types.add(c.dataset.type):state.types.delete(c.dataset.type);
  updateTypesLabel();render();
});
document.addEventListener("click",e=>{if(typesDd.open&&!e.target.closest("#typesdd"))typesDd.open=false;});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&typesDd.open){typesDd.open=false;typesSum.focus();}});

const atollEl=document.getElementById("atoll");
atollEl.innerHTML=`<option value="all">All atolls, north to south</option>`+ATOLLS.map(a=>`<option>${esc(a)}</option>`).join("");
atollEl.addEventListener("change",()=>{state.atoll=atollEl.value;state.sel=null;render();
  const pts=state.atoll==="all"?ROUTE_ISLES:ISL.filter(i=>i.atoll===state.atoll);
  map.flyToBounds(L.latLngBounds(pts.map(i=>[i.lat,i.lon])),{padding:[40,40],maxZoom:12,duration:.6});});

// search
const q=document.getElementById("q"), res=document.getElementById("results");
const norm=s=>String(s).toLowerCase().normalize("NFD").replace(/[̀-ͯ'’`]/g,"");
const INDEX=[
  ...ISL.map(i=>({sel:{kind:"isle",id:i.id},label:i.name,meta:`${CATNAME[i.cat].replace(" island","")} · ${i.atoll}`,rank:i.cat==="i"?0:i.cat==="r"?1:3,key:norm(`${i.name} ${i.atlasName} ${i.id} ${i.id==="k-hinmafushi"?"himmafushi hinmafushi":""}`)})),
  ...ROUTES.map(r=>({sel:{kind:"route",id:r.id},label:r.name,meta:(r.no?"#"+r.no+" · ":"")+TYPES[r.type].short,rank:0,key:norm(`${r.name} ${r.no||""} route ferry ${r.type}`)})),
  ...LAYERS.filter(l=>!ISLCAT[l.key]).flatMap(l=>l.items.map(it=>({sel:{kind:"poi",layer:l.key,idx:it.idx},label:it.name,meta:`${singular[l.key]} · ${it.atoll}`,rank:2,key:norm(`${it.name} ${singular[l.key]} ${it.extra.no||""}`)})))
];
let hits=[],cur=-1;
function showResults(){
  const v=norm(q.value.trim());
  if(!v){res.hidden=true;q.setAttribute("aria-expanded","false");return;}
  hits=INDEX.filter(x=>x.key.includes(v)).map(x=>({x,p:norm(x.label).startsWith(v)?0:1})).sort((a,b)=>a.p-b.p||a.x.rank-b.x.rank||a.x.label.localeCompare(b.x.label)).slice(0,10).map(o=>o.x);
  cur=hits.length?0:-1;
  res.innerHTML=hits.length?hits.map((h,k)=>`<li role="option" id="opt${k}" data-k="${k}" aria-selected="${k===cur}"><span>${esc(h.label)}</span><span class="k">${esc(h.meta)}</span></li>`).join("")
    :`<li class="none">Nothing called “${esc(q.value.trim())}” in the registers.</li>`;
  res.hidden=false;q.setAttribute("aria-expanded","true");
}
function pick(k){const h=hits[k];if(!h)return;q.value=h.label;res.hidden=true;q.setAttribute("aria-expanded","false");
  if(h.sel.kind==="route"&&!state.types.has(R[h.sel.id].type)){const t=R[h.sel.id].type;state.types.add(t);typesEl.querySelector(`[data-type="${t}"]`).setAttribute("aria-pressed","true");}
  select(h.sel,true);}
q.addEventListener("input",showResults);
q.addEventListener("focus",()=>{if(q.value.trim())showResults();});
q.addEventListener("keydown",e=>{
  if(res.hidden) return;
  if(e.key==="ArrowDown"||e.key==="ArrowUp"){e.preventDefault();if(!hits.length)return;cur=(cur+(e.key==="ArrowDown"?1:-1)+hits.length)%hits.length;
    res.querySelectorAll("li").forEach((li,k)=>li.setAttribute("aria-selected",k===cur));}
  else if(e.key==="Enter"){e.preventDefault();pick(cur);}
  else if(e.key==="Escape"){res.hidden=true;}
});
res.addEventListener("mousedown",e=>{const li=e.target.closest("li[data-k]");if(li){e.preventDefault();pick(+li.dataset.k);}});
document.addEventListener("click",e=>{if(!e.target.closest(".search")) res.hidden=true;});

// mobile sheet toggle
const panel=document.getElementById("panel"), tog=document.getElementById("toggle");
function openPanel(){panel.classList.remove("collapsed");tog.textContent="Hide panel";tog.setAttribute("aria-expanded","true");}
tog.addEventListener("click",()=>{const c=panel.classList.toggle("collapsed");tog.textContent=c?"Show panel":"Hide panel";tog.setAttribute("aria-expanded",String(!c));setTimeout(()=>map.invalidateSize(),50);});

// start
map.fitBounds(L.latLngBounds(ROUTE_ISLES.filter(i=>i.atoll!=="Seenu").map(i=>[i.lat,i.lon])),{padding:[30,30]});
zoomClasses();
paintHeat();
render();
new ResizeObserver(()=>map.invalidateSize()).observe(document.getElementById("map"));
})();
</script>

</body></html>